import { BRAND } from "@/branding";
import { Award, BarChart3, BookOpen, BrainCircuit, Check, ChevronLeft, ChevronRight, CircleHelp, Clock3, Dices, Download, FileUp, Flag, GraduationCap, History, LayoutDashboard, LockKeyhole, Menu, Moon, Plus, Search, ShieldCheck, Sparkles, Sun, Trophy, UsersRound, Volume2, VolumeX, WandSparkles, X } from "lucide-react";
import React, { ChangeEvent, FormEvent, Suspense, useEffect, useMemo, useState } from "react";
const AdminEnhanced = React.lazy(() => import("./AdminContentHub"));
const MuseumEnhanced = React.lazy(() => import("./MuseumJourney"));
const QuizEnhanced = React.lazy(() => import("./QuizEnhanced"));
const WheelEnhanced = React.lazy(() => import("./WheelEnhanced"));
const FocusHub = React.lazy(() => import("./FocusHub"));
const Pomodoro = React.lazy(() => import("./Pomodoro"));
const KnowledgeMap = React.lazy(() => import("./KnowledgeMap"));
const StudyHistory = React.lazy(() => import("./StudyHistory"));
const ExamPrep = React.lazy(() => import("./ExamPrep"));
const ProgressReports = React.lazy(() => import("./ProgressReports"));
const AIDataImport = React.lazy(() => import("./AIDataImport"));
import { toast } from "sonner";
import { allAchievementsWithProgress, applyStudyActivityRewards, computedAchievements, dailyLearningSummary, nearestAchievements, emptyAppConfig, validateGeneratedCards, validateGeneratedQuestions, emptyProfile, generateAchievements, levelForXp, normalizeProfile, statsForProfile, xpForNextLevel, limitFlashcards, type AppConfig, type Flashcard, type FlashcardSet, type ProfileState, type Quiz, type QuizQuestion, type StudyAccount, type StudySession } from "../../../shared/study";
import { createQuizFromFlashcardSet } from "../../../shared/quizPersistence";
import { canManageLearningConfig, isUnlimitedAccountCode } from "../../../shared/permissions";
import { addCustomAchievement, addWheelReward, deleteCustomAchievement, deleteWheelReward, toggleCustomAchievement, toggleWheelReward, updateCustomAchievement, updateWheelReward } from "../../../shared/learningConfigActions";
