type View = "dashboard" | "focus" | "pomodoro" | "knowledge" | "history" | "exam" | "progress" | "studio" | "ai-import" | "flashcards" | "quizzes" | "achievements" | "museum" | "wheel" | "account" | "admin" | "special111";
const SESSION_KEY = "study_historia_session_v1";
const uid = () => crypto.randomUUID();
const isAdmin = (a: StudyAccount) => canManageLearningConfig(a.role);
const nav: { id: View; label: string; icon: typeof LayoutDashboard; admin?: boolean; special111?: boolean }[] = [
  { id: "dashboard", label: "Trang chủ", icon: LayoutDashboard }, { id: "special111", label: "Trung tâm 111", icon: WandSparkles, special111: true }, { id: "focus", label: "Ôn tập thông minh", icon: Sparkles }, { id: "ai-import", label: "Nhập dữ liệu AI", icon: FileUp }, { id: "pomodoro", label: "Pomodoro", icon: Clock3 }, { id: "knowledge", label: "Bản đồ kiến thức", icon: BarChart3 }, { id: "history", label: "Lịch sử học", icon: History }, { id: "exam", label: "Tôi sắp kiểm tra", icon: Flag }, { id: "progress", label: "Tiến trình", icon: BarChart3 }, { id: "studio", label: "AI Studio", icon: BrainCircuit }, { id: "flashcards", label: "Flashcard", icon: BookOpen }, { id: "quizzes", label: "Đề kiểm tra", icon: CircleHelp }, { id: "achievements", label: "Thành tích", icon: Trophy }, { id: "museum", label: "Bảo tàng hành trình", icon: History }, { id: "wheel", label: "Vòng quay tri thức", icon: Dices }, { id: "account", label: "Tài khoản", icon: UsersRound }, { id: "admin", label: "Admin Panel", icon: ShieldCheck, admin: true },
];

function storedSession(): StudySession | null { try { const item = sessionStorage.getItem(SESSION_KEY); return item ? JSON.parse(item) as StudySession : null; } catch { return null; } }
function parseCards(value: string): Flashcard[] { try { const raw = JSON.parse(value); const list = Array.isArray(raw) ? raw : raw?.cards; if (!Array.isArray(list)) return []; const cards = list.map((x) => ({ id: uid(), front: String(x.front ?? x.question ?? "").trim(), back: String(x.back ?? x.answer ?? "").trim(), status: "new" as const, starred: false })).filter((x) => x.front && x.back); return limitFlashcards(cards); } catch { return []; } }
function parseQuestions(value: string): QuizQuestion[] { try { const raw = JSON.parse(value); const list = Array.isArray(raw) ? raw : raw.questions; if (!Array.isArray(list)) return []; return list.map((x) => ({ id: uid(), type: x.type === "boolean" || x.type === "short" ? x.type : "multiple", prompt: String(x.prompt ?? x.question ?? ""), options: Array.isArray(x.options) ? x.options.map(String) : undefined, answer: String(x.answer ?? ""), explanation: String(x.explanation ?? "") })).filter((x) => x.prompt && x.answer); } catch { return []; } }

export default function Home() {
  const [session, setSession] = useState<StudySession | null>(() => isGitHubPages ? null : storedSession());
  const [profile, setProfile] = useState<ProfileState>(emptyProfile());
  const [config, setConfig] = useState<AppConfig>(emptyAppConfig());
  const [view, setView] = useState<View>("dashboard");
  const [menu, setMenu] = useState(false);
  const [cloudBusy, setCloudBusy] = useState(false);
  const [loginError, setLoginError] = useState("");
  const [search, setSearch] = useState("");
  const token = session?.token ?? "";
  const login = trpc.study.auth.login.useMutation();
  const logout = trpc.study.auth.logout.useMutation();
  const profileData = trpc.study.profile.get.useQuery({ token: token || "invalid-token" }, { enabled: Boolean(token) && !isGitHubPages, retry: false });
  const configData = trpc.study.config.get.useQuery(undefined, { enabled: !isGitHubPages, retry: false });
  const saveProfile = trpc.study.profile.save.useMutation();
  const saveConfig = trpc.study.config.save.useMutation();
  useEffect(() => { if (profileData.data?.profile) setProfile(normalizeProfile(profileData.data.profile)); }, [profileData.data]);
  useEffect(() => { if (!isGitHubPages) return; let active = true; void cloudRestoreSession().then(async (data) => { if (!active || !data) return; setSession(data); const [nextProfile, nextConfig] = await Promise.all([cloudLoadProfile(data.account.id), cloudLoadConfig()]); if (active) { setProfile(nextProfile); setConfig(nextConfig); } }).catch(() => undefined); return () => { active = false; }; }, []);
  useEffect(() => { if (configData.data) setConfig(configData.data as AppConfig); }, [configData.data]);
  useEffect(() => { if (profileData.error) { sessionStorage.removeItem(SESSION_KEY); setSession(null); } }, [profileData.error]);
  useEffect(() => {
    const root = document.documentElement;
    const applyAppearance = () => {
      const hour = new Date().getHours();
      const shouldUseNight = profile.autoNightMode === true && (hour >= 19 || hour < 6);
      root.classList.toggle("dark", shouldUseNight || profile.theme === "dark");
      root.dataset.focusMode = profile.focusMode === true ? "true" : "false";
      delete root.dataset.cosmeticTheme;
      delete root.dataset.cosmeticBackground;
    };
    applyAppearance();
    const timer = profile.autoNightMode === true ? window.setInterval(applyAppearance, 60_000) : undefined;
    return () => { if (timer) window.clearInterval(timer); };
  }, [profile.autoNightMode, profile.focusMode, profile.theme]);
  useEffect(() => {
    if (typeof window === "undefined" || !("IntersectionObserver" in window)) return;
    const root = document.querySelector("main[data-scroll-reveal-root]");
    if (!root) return;
    const targets = Array.from(root.querySelectorAll<HTMLElement>("section, article, .panel, .study-card, [data-scroll-item]"));
    targets.forEach((target, index) => { target.classList.add("scroll-reveal"); target.style.setProperty("--reveal-delay", `${Math.min(index % 6, 5) * 45}ms`); });
    const observer = new IntersectionObserver((entries) => entries.forEach((entry) => { if (entry.isIntersecting) { entry.target.classList.add("is-visible"); observer.unobserve(entry.target); } }), { threshold: 0.08, rootMargin: "0px 0px -8% 0px" });
    targets.forEach((target) => observer.observe(target));
    return () => observer.disconnect();
  }, [view, session]);
  const persistProfile = (next: ProfileState, message?: string) => { const normalized = normalizeProfile(next); setProfile(normalized); if (isGitHubPages) { void cloudSaveProfile(session!.account.id, normalized).then(() => message && toast.success(message)).catch((e) => toast.error(e instanceof Error ? e.message : "Không thể đồng bộ hồ sơ.")); return; } saveProfile.mutate({ token, profile: normalized }, { onSuccess: () => message && toast.success(message), onError: (e) => toast.error(e.message) }); };
  const persistConfig = (next: AppConfig, message?: string) => { setConfig(next); if (isGitHubPages) { void cloudSaveConfig(next).then(() => message && toast.success(message)).catch((e) => toast.error(e instanceof Error ? e.message : "Không thể đồng bộ cấu hình.")); return; } saveConfig.mutate({ token, config: next }, { onSuccess: () => message && toast.success(message), onError: (e) => toast.error(e.message) }); };
  const applySession = (data: StudySession) => { sessionStorage.setItem(SESSION_KEY, JSON.stringify(data)); setSession(data); toast.success(`Chào mừng ${data.account.name}`); };
  const submitLogin = async (data: { name: string; password: string; code: string; email?: string }) => {
    setLoginError("");
    if (isGitHubPages) { setCloudBusy(true); try { const result = await cloudLogin(data); applySession(result); setProfile(await cloudLoadProfile(result.account.id)); setConfig(await cloudLoadConfig()); } catch (e) { const message = e instanceof Error ? e.message : "Thông tin đăng nhập không chính xác."; setLoginError(message); toast.error(message); } finally { setCloudBusy(false); } return; }
    login.mutate({ name: data.name, password: data.password, code: data.code }, { onSuccess: applySession, onError: (e) => { setLoginError(e.message || "Thông tin đăng nhập không chính xác."); toast.error(e.message); } });
  };
  if (!session) return <Login onSubmit={submitLogin} loading={login.isPending || cloudBusy} error={loginError} staticHost={isGitHubPages} />;
  const account = session.account;
  const enabledLevelDefinitions = (config.levelDefinitions ?? []).filter((item) => item.enabled && !item.deletedAt);
  const currentLevelDefinition = enabledLevelDefinitions.length ? enabledLevelDefinitions[(Math.max(1, profile.level) - 1) % enabledLevelDefinitions.length] : undefined;
  const matches = search ? [...profile.flashcardSets.map((x) => ({ label: x.title, to: "flashcards" as View })), ...profile.quizzes.map((x) => ({ label: x.title, to: "quizzes" as View })), ...computedAchievements(profile, config).map((x) => ({ label: `${x.title} · Thành tích`, to: "achievements" as View })), ...config.characters.flatMap((x) => [{ label: x.name, to: "museum" as View }, { label: `Mảnh ghép · ${x.name}`, to: "museum" as View }])].filter((x) => x.label.toLowerCase().includes(search.toLowerCase())).slice(0, 5) : [];
  return <div className="min-h-screen bg-[#fffdf8] text-slate-800 dark:bg-[#241b16] dark:text-slate-100"><aside className={cn("fixed inset-y-0 left-0 z-50 flex w-72 flex-col border-r border-[#eadfd2] bg-white/95 p-4 backdrop-blur dark:border-white/10 dark:bg-[#241b16]/95 xl:translate-x-0", menu ? "translate-x-0" : "-translate-x-full", "transition-transform")}><Brand /><div className="my-6 flex items-center gap-3 rounded-2xl bg-[#fff7dc] p-3 dark:bg-[#3a2a1d]"><LumiMascot size="sidebar" /><p className="text-xs font-bold leading-5 text-[#8e1b1b] dark:text-amber-100">Lumi đồng hành<br /><span className="font-medium text-amber-800/80 dark:text-amber-200/80">Mỗi ngày một bước tiến</span></p></div> <nav className="mt-2 space-y-1">{nav.filter((x) => (!x.admin || isAdmin(account)) && (!x.special111 || isUnlimitedAccountCode(account.code))).map((x) => <Nav key={x.id} item={x} active={view === x.id} onClick={() => { setView(x.id); setMenu(false); }} />)}</nav><div className="mt-auto rounded-3xl bg-gradient-to-br from-[#8e1b1b] to-[#c62828] p-4 text-white"><p className="text-xs font-bold uppercase tracking-widest text-red-100">Cấp hiện tại</p><p className="mt-2 font-display text-3xl font-bold">Cấp {profile.level}</p><p className="mt-1 text-sm font-bold text-amber-100">{currentLevelDefinition ? `${currentLevelDefinition.icon} ${currentLevelDefinition.name}` : "🌱 Hành trình học tập"}</p><p className="mt-1 text-sm text-red-100">{profile.xp.toLocaleString("vi-VN")} XP</p><Progress value={Math.min(100, profile.xp / xpForNextLevel(profile.level) * 100)} className="mt-4 bg-white/20" /></div></aside>{menu && <button className="fixed inset-0 z-40 bg-slate-950/50 xl:hidden" onClick={() => setMenu(false)} aria-label="Đóng menu" />}<div className="xl:pl-72"><header className="sticky top-0 z-30 flex h-[74px] items-center gap-3 border-b border-[#eadfd2] bg-[#fffdf8]/95 px-4 backdrop-blur dark:border-white/10 dark:bg-[#241b16]/90 sm:px-7"><button onClick={() => setMenu(true)} className="icon-button xl:hidden" aria-label="Mở menu"><Menu className="h-5 w-5" /></button><div className="relative max-w-xl flex-1"><Search className="absolute left-3 top-3 h-4 w-4 text-slate-400" /><input aria-label={`Tìm kiếm trong ${BRAND.naturalName}`} value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Tìm Flashcard, đề, nhân vật…" className="h-10 w-full rounded-xl border border-[#eadfd2] bg-white pl-9 pr-3 text-sm outline-none focus:border-[#c62828] focus:ring-2 focus:ring-[#c62828]/15 dark:border-white/10 dark:bg-slate-900" />{matches.length > 0 && <div className="absolute top-12 w-full rounded-xl border border-slate-200 bg-white p-1 shadow-xl dark:border-white/10 dark:bg-slate-900">{matches.map((x, i) => <button aria-label={`Mở kết quả tìm kiếm: ${x.label}`} key={i} onClick={() => { setView(x.to); setSearch(""); }} className="block w-full rounded-lg px-3 py-2 text-left text-sm hover:bg-slate-50 dark:hover:bg-white/5">{x.label}</button>)}</div>}</div><button aria-label={profile.theme === "dark" ? "Chuyển sang chế độ sáng" : "Chuyển sang chế độ tối"} onClick={() => persistProfile({ ...profile, theme: profile.theme === "dark" ? "light" : "dark" })} className="icon-button">{profile.theme === "dark" ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}</button><button aria-label={profile.soundEnabled ? "Tắt âm thanh" : "Bật âm thanh"} onClick={() => persistProfile({ ...profile, soundEnabled: !profile.soundEnabled })} className="icon-button">{profile.soundEnabled ? <Volume2 className="h-4 w-4" /> : <VolumeX className="h-4 w-4" />}</button><div className="hidden gap-2 border-l border-slate-200 pl-3 sm:flex dark:border-white/10"><span className="grid h-10 w-10 place-items-center rounded-full bg-gradient-to-br from-[#f4b942] to-[#c62828] font-bold text-white">{account.name[0]}</span><span className="hidden lg:block"><b className="block max-w-32 truncate text-sm">{account.name}</b><small className="text-xs text-slate-500">{account.role}</small></span></div></header><main data-scroll-reveal-root className="mx-auto max-w-[1500px] p-4 sm:p-7"><Views view={view} account={account} profile={profile} config={config} token={token} onView={setView} onProfile={persistProfile} onConfig={persistConfig} onLogout={() => { if (isGitHubPages) cloudSignOut(); else logout.mutate({ token }); sessionStorage.removeItem(SESSION_KEY); setSession(null); }} /></main></div><MenuHelpGuide currentView={view} isAdmin={isAdmin(account)} isUnlimitedAccount={isUnlimitedAccountCode(account.code)} onNavigate={(nextView) => setView(nextView)} /></div>;
}

export function Login({ onSubmit, loading, error, staticHost = false }: { onSubmit: (data: { name: string; password: string; code: string; email?: string }) => void | Promise<void>; loading: boolean; error?: string; staticHost?: boolean }) {
  const submit = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const d = new FormData(e.currentTarget); onSubmit({ name: String(d.get("name") ?? ""), password: String(d.get("password") ?? ""), code: String(d.get("code") ?? "") }); };
  const reset = () => openFullstackLogin();
  const [helpTopic, setHelpTopic] = useState<"password" | "code" | null>(null);
  const helpTitle = helpTopic === "password" ? "Quên mật khẩu" : "Quên mã thành viên";
  const helpText = helpTopic === "password" ? "Vì hệ thống không dùng email, mật khẩu không thể tự đặt lại bằng liên kết. Vui lòng liên hệ Founder hoặc Admin để xác minh danh tính và cấp lại mật khẩu." : "Mã thành viên được Founder hoặc Admin cấp và quản lý. Hãy gửi tên hiển thị cùng lý do cần hỗ trợ cho quản trị viên.";
  return <main className="min-h-screen bg-[radial-gradient(circle_at_12%_8%,#f4b94233,transparent_26%),radial-gradient(circle_at_88%_90%,#43a04722,transparent_30%),#fffdf8] px-5 py-10 text-slate-900"><div className="mx-auto grid min-h-[calc(100vh-5rem)] max-w-6xl items-center gap-10 lg:grid-cols-2"><section className="hidden lg:block"><div className="flex items-start justify-between gap-5"><div><Brand /><p className="mt-16 text-xs font-bold uppercase tracking-[.25em] text-[#8e1b1b]">Học · Chinh phục · Khám phá</p><h1 className="mt-5 max-w-xl font-display text-6xl font-bold leading-tight text-[#8e1b1b]">Mỗi lần học là một bước mở khóa câu chuyện.</h1><p className="mt-6 max-w-lg text-lg leading-8 text-slate-600">Flashcard, kiểm tra và hành trình khám phá lịch sử Việt Nam được kết nối trong một góc học tập riêng cho từng thành viên.</p></div><div className="flex items-end gap-3"><LumiMascot /><OngMascot /></div></div></section><form onSubmit={submit} className="mx-auto w-full max-w-md rounded-[2rem] border border-[#eadfd2] bg-white p-7 shadow-[0_24px_70px_rgba(142,27,27,.12)]"><div className="mb-5 flex items-center justify-between gap-2 lg:hidden"><Brand /><div className="flex items-center gap-1"><LumiMascot size="compact" /><OngMascot size="compact" /></div></div><p className="mt-7 text-xs font-bold uppercase tracking-[.2em] text-[#2e7d32]">Phiên học riêng tư</p><h2 className="mt-2 font-display text-3xl font-bold text-[#8e1b1b]">Chào mừng trở lại</h2>
<p className="mt-2 text-sm text-slate-600">{staticHost ? "Đăng nhập không email bằng tên, mật khẩu và mã thành viên; mã 111 sẽ tạo tài khoản ở lần đầu." : noEmailLoginHint}</p>
<div className="mt-7 space-y-4">{<Field name="name" label="Tên thành viên" placeholder="Ví dụ: Nguyễn Văn An" />}<Field name="password" type="password" label="Mật khẩu" placeholder="Tối thiểu 6 ký tự" /><label className="flex items-center gap-2 text-xs font-semibold text-slate-500"><input type="checkbox" onChange={(e) => { const input = e.currentTarget.form?.elements.namedItem("password"); if (input instanceof HTMLInputElement) input.type = e.currentTarget.checked ? "text" : "password"; }} /> Xem mật khẩu</label><Field name="code" label="Mã thành viên" placeholder="Ví dụ: 111 hoặc mã được cấp" /><div className="flex flex-wrap justify-between gap-2 text-xs font-semibold"><button type="button" onClick={() => setHelpTopic("password")} className="text-[#8e1b1b] underline underline-offset-4">Quên mật khẩu?</button><button type="button" onClick={() => setHelpTopic("code")} className="text-[#8e1b1b] underline underline-offset-4">Quên mã thành viên?</button></div>{error && <p role="alert" className="rounded-xl border border-red-300 bg-red-50 px-3 py-2.5 text-sm font-semibold leading-5 text-red-700">{error}</p>}<button type="submit" aria-label={loading ? "Đang kiểm tra thông tin" : staticHost ? "Đăng nhập cloud-state" : "Đăng nhập vào hành trình"} aria-busy={loading} disabled={loading} className="w-full rounded-xl bg-[#c62828] px-4 py-3.5 text-sm font-bold text-white shadow-lg shadow-red-900/15 transition hover:bg-[#8e1b1b] disabled:opacity-60">{loading ? "Đang xử lý…" : "Đăng nhập vào hành trình"}</button>{staticHost && <button type="button" disabled={loading} onClick={reset} className="w-full text-sm font-semibold text-[#8e1b1b] underline-offset-4 hover:underline">Mở bản full-stack để đăng nhập</button>}</div><p className={cn("mt-5 rounded-xl border p-3 text-xs leading-5", staticHost ? "border-amber-200 bg-amber-50 text-amber-800" : "border-[#dcebdc] bg-[#f5f7f2] text-[#2e7d32]")}>{staticHost ? cloudStateWarning : "Lần đầu đăng nhập bằng mã 111: nhập tên của bạn, mật khẩu mới tối thiểu 6 ký tự và mã 111. Các mã khác phải được Admin/Founder cấp trước."}</p></form>{helpTopic && <div role="dialog" aria-modal="true" aria-labelledby="login-help-title" className="fixed inset-0 z-50 grid place-items-center bg-slate-950/45 p-5"><div className="w-full max-w-md rounded-3xl bg-white p-6 text-slate-900 shadow-2xl"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-amber-700">Hỗ trợ đăng nhập</p><h3 id="login-help-title" className="mt-2 font-display text-2xl font-bold text-[#8e1b1b]">{helpTitle}</h3></div><button type="button" aria-label="Đóng hướng dẫn" onClick={() => setHelpTopic(null)} className="rounded-full p-2 text-slate-500 hover:bg-slate-100"><X className="h-5 w-5" /></button></div><p className="mt-4 text-sm leading-6 text-slate-600">{helpText}</p><button type="button" onClick={() => setHelpTopic(null)} className="mt-6 w-full rounded-xl bg-[#c62828] px-4 py-3 text-sm font-bold text-white hover:bg-[#8e1b1b]">Đã hiểu</button></div></div>}</div></main>;
}
function LumiMascot({ size = "hero" }: { size?: "hero" | "compact" | "sidebar" }) { const styles = size === "hero" ? "h-56 w-48 sm:h-64 sm:w-56" : size === "sidebar" ? "h-28 w-24" : "h-20 w-16"; return <div aria-label="Lumi, bạn đồng hành của Ong" role="img" className={cn("lumi-mascot relative overflow-hidden rounded-[2.4rem] border-4 border-white bg-[#f8e7cf] shadow-[0_18px_45px_rgba(142,27,27,.2)]", styles)}><img src="/manus-storage/lumi-mascot-clean_28a6da68.png" alt="Lumi đeo kính với kẹp tóc hình ngôi sao vàng" className="h-full w-full object-cover object-top" /><span className="absolute bottom-1 left-1/2 -translate-x-1/2 rounded-full border-2 border-white bg-[#2e7d32] px-3 py-1 text-[10px] font-black uppercase tracking-[.18em] text-white shadow-md">Lumi</span></div>; }
function OngMascot({ size = "compact" }: { size?: "compact" | "sidebar" }) { return <div className="relative"><OngLearnerAvatar size={size === "sidebar" ? "lg" : "md"} label /><span className="absolute bottom-6 left-1/2 -translate-x-1/2 rounded-full border-2 border-white bg-[#f4b942] px-3 py-1 text-[10px] font-black uppercase tracking-[.18em] text-[#5b1717] shadow-md">Ong</span></div>; }
