function EmotionThemeController({ profile, onProfile, children }: { profile: ProfileState; onProfile: (profile: ProfileState, message?: string) => void; children: React.ReactNode }) {
  const selected = profile.emotionTheme ?? "calm";
  const theme = emotionThemes.find((item) => item.id === selected) ?? emotionThemes[0];

  useEffect(() => {
    const root = document.documentElement;
    const applyTheme = () => {
      if (root.dataset.emotion !== theme.id) root.dataset.emotion = theme.id;
      root.style.setProperty("--emotion-primary", theme.colors.primary);
      root.style.setProperty("--emotion-secondary", theme.colors.secondary);
      root.style.setProperty("--emotion-soft", theme.colors.soft);
      root.style.setProperty("--emotion-ink", theme.colors.ink);
      root.style.setProperty("--emotion-glow", theme.colors.glow);
      window.localStorage.setItem("study-empire:emotion-theme", theme.id);
    };
    applyTheme();
    const observer = new MutationObserver(() => { if (root.dataset.emotion !== theme.id) applyTheme(); });
    observer.observe(root, { attributes: true, attributeFilter: ["data-emotion"] });
    return () => observer.disconnect();
  }, [theme]);

  useEffect(() => {
    const root = document.documentElement;
    root.dataset.animations = profile.animationsEnabled === false ? "off" : "on";
    root.dataset.popups = profile.popupsEnabled === false ? "off" : "on";
    root.dataset.sound = profile.soundEnabled === false ? "off" : "on";
    root.dataset.ambientScene = profile.defaultAmbientScene ?? "morning";
  }, [profile.animationsEnabled, profile.defaultAmbientScene, profile.popupsEnabled, profile.soundEnabled]);

  useEffect(() => {
    const handleEmotionChange = (event: Event) => {
      const next = (event as CustomEvent<unknown>).detail;
      if (!emotionThemes.some((item) => item.id === next) || next === selected) return;
      onProfile({ ...profile, emotionTheme: next as EmotionId });
    };
    window.addEventListener("study-empire:emotion-change", handleEmotionChange);
    return () => window.removeEventListener("study-empire:emotion-change", handleEmotionChange);
  }, [onProfile, profile, selected]);

  return <>{children}</>;
}

function Views({ view, account, profile, config, token, onView, onProfile, onConfig, onLogout }: { view: View; account: StudyAccount; profile: ProfileState; config: AppConfig; token: string; onView: (v: View) => void; onProfile: (p: ProfileState, m?: string) => void; onConfig: (c: AppConfig, m?: string) => void; onLogout: () => void }) {
  let content: React.ReactNode;
  if (view === "dashboard") { content = <Dashboard account={account} profile={profile} config={config} onView={onView} onProfile={onProfile} />; }
  else if (view === "special111") { content = isUnlimitedAccountCode(account.code) ? <Special111Dashboard account={account} profile={profile} onView={onView} /> : <Dashboard account={account} profile={profile} config={config} onView={onView} onProfile={onProfile} />; }
  else if (view === "focus") { content = <FocusHub profile={profile} config={config} onView={onView} onProfile={onProfile} />; }
  else if (view === "pomodoro") { content = <Pomodoro profile={profile} config={config} onProfile={onProfile} onView={onView} />; }
  else if (view === "knowledge") { content = <KnowledgeMap profile={profile} onView={onView} />; }
  else if (view === "history") { content = <StudyHistory profile={profile} />; }
  else if (view === "exam") { content = <ExamPrep profile={profile} onView={onView} />; }
  else if (view === "progress") { content = <><LearningProgress profile={profile} onView={onView} /><ProgressReports profile={profile} /></>; }
  else if (view === "studio") { content = <Studio profile={profile} onProfile={onProfile} onView={onView} token={token} />; }
  else if (view === "ai-import") { content = <AIDataImport profile={profile} onProfile={onProfile} onView={onView} />; }
  else if (view === "flashcards") { content = <Cards profile={profile} config={config} onProfile={onProfile} />; }
  else if (view === "quizzes") { content = <QuizEnhanced profile={profile} config={config} onProfile={onProfile} />; }
  else if (view === "achievements") { content = <Achievements profile={profile} config={config} />; }
  else if (view === "museum") { content = <MuseumEnhanced account={account} profile={profile} config={config} onView={onView} onProfile={onProfile} />; }
  else if (view === "wheel") { content = <WheelEnhanced profile={profile} config={config} onProfile={onProfile} />; }
  else if (view === "account") { content = <Account account={account} profile={profile} config={config} onProfile={onProfile} onLogout={onLogout} />; }
  else { content = <AdminEnhanced account={account} profile={profile} config={config} onConfig={onConfig} />; }
  return <EmotionThemeController profile={profile} onProfile={onProfile}><Suspense fallback={<div className="panel mx-auto mt-8 max-w-3xl p-8 text-center"><p className="font-display text-lg font-bold">Lumi đang mở không gian học…</p><p className="mt-2 text-sm text-slate-500">Chỉ tải module khi Ong cần dùng.</p></div>}>{content}</Suspense></EmotionThemeController>;
}
function LearningProgress({ profile, onView }: { profile: ProfileState; onView: (view: View) => void }) { const stats = statsForProfile(profile); const activity = profile.studyActivity.length ? profile.studyActivity : profile.attempts.map((attempt) => ({ id: `legacy-${attempt.id}`, occurredAt: attempt.completedAt, kind: "quiz" as const, quantity: attempt.total, durationSeconds: attempt.durationSeconds, xpEarned: 0, correct: attempt.correct, total: attempt.total })); const todayStart = new Date(); todayStart.setHours(0, 0, 0, 0); const weekStart = new Date(todayStart); weekStart.setDate(weekStart.getDate() - 6); const today = activity.filter((item) => new Date(item.occurredAt) >= todayStart); const week = activity.filter((item) => new Date(item.occurredAt) >= weekStart); const quizAttempts = profile.attempts.filter((attempt) => new Date(attempt.completedAt) >= weekStart); const totalCorrect = quizAttempts.reduce((sum, attempt) => sum + attempt.correct, 0); const totalQuestions = quizAttempts.reduce((sum, attempt) => sum + attempt.total, 0); const studyDays = new Set(activity.map((item) => new Date(item.occurredAt).toLocaleDateString("vi-VN"))); const recentDays = Array.from({ length: 7 }, (_, index) => { const day = new Date(todayStart); day.setDate(day.getDate() - (6 - index)); const key = day.toLocaleDateString("vi-VN"); const count = activity.filter((item) => new Date(item.occurredAt).toLocaleDateString("vi-VN") === key).reduce((sum, item) => sum + item.quantity, 0); return { label: day.toLocaleDateString("vi-VN", { weekday: "short" }).replace("T", "T"), count }; }); const maxDaily = Math.max(1, ...recentDays.map((day) => day.count)); const quizById = new Map(profile.quizzes.map((quiz) => [quiz.id, quiz])); const modeRows = (["quick", "deep", "paper"] as const).map((mode) => { const attempts = profile.attempts.filter((attempt) => (attempt.mode ?? "quick") === mode); const correct = attempts.reduce((sum, attempt) => sum + attempt.correct, 0); const total = attempts.reduce((sum, attempt) => sum + attempt.total, 0); return { mode, label: mode === "quick" ? "Làm đề nhanh" : mode === "deep" ? "Hiểu tận gốc" : "Tự làm đề–Tập trung", count: attempts.length, accuracy: total ? Math.round(correct / total * 100) : 0 }; }); const topicMap = new Map<string, { subject: string; topic: string; attempts: number; correct: number; total: number }>(); profile.attempts.forEach((attempt) => { const quiz = quizById.get(attempt.quizId); const subject = quiz?.subject || "Chưa phân loại"; const topic = quiz?.topic || quiz?.title || "Chưa có chủ đề"; const key = `${subject} · ${topic}`; const row = topicMap.get(key) ?? { subject, topic, attempts: 0, correct: 0, total: 0 }; row.attempts += 1; row.correct += attempt.correct; row.total += attempt.total; topicMap.set(key, row); }); const topicRows = Array.from(topicMap.values()).sort((a, b) => (b.correct / Math.max(1, b.total)) - (a.correct / Math.max(1, a.total))).slice(0, 6).map((row) => ({ ...row, accuracy: Math.round(row.correct / Math.max(1, row.total) * 100) })); const formatDuration = (seconds: number) => { const minutes = Math.round(seconds / 60); return minutes >= 60 ? `${Math.floor(minutes / 60)} giờ ${minutes % 60} phút` : `${minutes} phút`; }; return <><Heading eyebrow="Tiến trình học tập" title="Dữ liệu của chính hành trình bạn" text="Báo cáo chỉ tổng hợp lượt học, đề đã nộp và thời lượng đã ghi nhận trong hồ sơ của bạn." action={<button className="primary-button" onClick={() => onView("pomodoro")}><Clock3 className="h-4 w-4" />Mở Pomodoro</button>} /><section className="panel mb-5 flex flex-wrap items-center justify-between gap-4 p-5"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-amber-700 dark:text-amber-300">Module trung tâm</p><h2 className="mt-2 font-display text-2xl font-bold">Pomodoro · biến thời gian thành tiến trình</h2><p className="mt-2 text-sm text-slate-500">Phiên hoàn thành liên kết với Flashcard, Đề kiểm tra, XP, Thành tích và Mảnh ghép mà không trộn dữ liệu các module.</p></div><div className="flex flex-wrap gap-2"><button className="secondary-button" onClick={() => onView("flashcards")}><BookOpen className="h-4 w-4" />Flashcard</button><button className="secondary-button" onClick={() => onView("quizzes")}><CircleHelp className="h-4 w-4" />Đề kiểm tra</button></div></section><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat icon={BookOpen} label="Lượt học hôm nay" value={today.reduce((sum, item) => sum + item.quantity, 0)} detail={`${today.filter((item) => item.kind === "flashcard").length} lần ôn thẻ`} /><Stat icon={Clock3} label="Thời gian đã ghi nhận" value={formatDuration(stats.studySeconds)} detail="Từ đề kiểm tra đã nộp" /><Stat icon={CircleHelp} label="Độ chính xác 7 ngày" value={totalQuestions ? `${Math.round(totalCorrect / totalQuestions * 100)}%` : "—"} detail={totalQuestions ? `${totalCorrect}/${totalQuestions} câu đúng` : "Chưa có đề trong 7 ngày"} /><Stat icon={Sparkles} label="Ngày có hoạt động" value={studyDays.size} detail="Tính trên toàn bộ lịch sử" /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.35fr_.85fr]"><section className="panel p-6"><div className="flex items-end justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-amber-700 dark:text-amber-300">7 ngày gần đây</p><h2 className="mt-2 font-display text-2xl font-bold">Nhịp học theo ngày</h2></div><b className="text-sm text-slate-500">{week.reduce((sum, item) => sum + item.quantity, 0)} lượt học</b></div><div className="mt-8 grid h-48 grid-cols-7 items-end gap-3" role="img" aria-label="Biểu đồ lượt học trong bảy ngày gần đây">{recentDays.map((day) => <div className="flex h-full flex-col justify-end" key={day.label}><div className="rounded-t-xl bg-gradient-to-t from-amber-500 to-yellow-300 transition-[height]" style={{ height: `${Math.max(day.count ? 14 : 3, day.count / maxDaily * 100)}%` }} title={`${day.label}: ${day.count} lượt học`} /><span className="mt-2 text-center text-[11px] font-bold text-slate-500">{day.label}</span></div>)}</div></section><section className="panel p-6"><p className="text-xs font-bold uppercase tracking-[.16em] text-amber-700 dark:text-amber-300">Tổng hành trình</p><h2 className="mt-2 font-display text-2xl font-bold">Học một cách có chủ đích</h2><dl className="mt-6 space-y-4 text-sm"><div className="flex justify-between gap-4"><dt className="text-slate-500">Flashcard đã nhớ</dt><dd className="font-bold">{stats.learnedCards}</dd></div><div className="flex justify-between gap-4"><dt className="text-slate-500">Bộ hoàn tất</dt><dd className="font-bold">{stats.completedSets}</dd></div><div className="flex justify-between gap-4"><dt className="text-slate-500">Đề đã hoàn thành</dt><dd className="font-bold">{stats.completedQuizzes}</dd></div><div className="flex justify-between gap-4"><dt className="text-slate-500">XP tích lũy</dt><dd className="font-bold">{profile.xp.toLocaleString("vi-VN")}</dd></div></dl></section></div><div className="mt-5 grid gap-5 xl:grid-cols-2"><section className="panel p-6" aria-labelledby="progress-mode-chart"><p className="text-xs font-bold uppercase tracking-[.16em] text-amber-700 dark:text-amber-300">Theo chế độ</p><h2 id="progress-mode-chart" className="mt-2 font-display text-2xl font-bold">Cách bạn đang học</h2><div className="mt-6 space-y-4">{modeRows.map((row) => <div key={row.mode}><div className="mb-2 flex items-center justify-between gap-3 text-sm"><span className="font-bold">{row.label}</span><span className="text-slate-500">{row.count} phiên · {row.accuracy}% đúng</span></div><div className="h-3 overflow-hidden rounded-full bg-slate-100 dark:bg-white/10"><div className="h-full rounded-full bg-gradient-to-r from-amber-500 to-yellow-300" style={{ width: `${row.count ? Math.max(8, row.accuracy) : 0}%` }} /></div></div>)}</div></section><section className="panel p-6" aria-labelledby="progress-topic-chart"><p className="text-xs font-bold uppercase tracking-[.16em] text-amber-700 dark:text-amber-300">Theo chủ đề</p><h2 id="progress-topic-chart" className="mt-2 font-display text-2xl font-bold">Chủ đề nổi bật</h2>{topicRows.length ? <div className="mt-5 space-y-3">{topicRows.map((row) => <div className="rounded-2xl border border-slate-100 p-3 dark:border-white/10" key={`${row.subject}-${row.topic}`}><div className="flex items-center justify-between gap-3"><div className="min-w-0"><b className="block truncate text-sm">{row.topic}</b><span className="text-xs text-slate-500">{row.subject} · {row.attempts} phiên</span></div><strong className="text-sm text-amber-700">{row.accuracy}%</strong></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-slate-100 dark:bg-white/10"><div className="h-full rounded-full bg-emerald-500" style={{ width: `${row.accuracy}%` }} /></div></div>)}</div> : <p className="mt-5 text-sm text-slate-500">Chưa có dữ liệu chủ đề từ các đề đã hoàn thành.</p>}</section></div></>; }
function Special111Dashboard({ account, profile, onView }: { account: StudyAccount; profile: ProfileState; onView: (v: View) => void }) { const quick = [{ icon: Sparkles, label: "Ôn tập thông minh", detail: "Bắt đầu một nhịp học ngắn", view: "focus" as View }, { icon: Clock3, label: "Pomodoro", detail: "Tập trung và ghi nhận phiên", view: "pomodoro" as View }, { icon: BrainCircuit, label: "AI Studio", detail: "Tạo Flashcard hoặc Đề kiểm tra", view: "studio" as View }, { icon: Trophy, label: "Thành tích", detail: "Theo dõi 900 mốc tiến bộ", view: "achievements" as View }]; return <><Heading eyebrow="Khu vực đặc biệt · Mã 111" title={`Trung tâm điều khiển của ${account.name}`} text="Tài khoản 111 được miễn giới hạn. Từ đây, Ong có thể mở nhanh các công cụ học tập cốt lõi và theo dõi nhịp học của mình." action={<span className="rounded-full border border-amber-300 bg-amber-50 px-4 py-2 text-xs font-bold text-amber-800 dark:border-amber-400/30 dark:bg-amber-400/10 dark:text-amber-200">Mã 111 · Không giới hạn</span>} /><section className="mb-5 overflow-hidden rounded-[2rem] bg-gradient-to-br from-[#6b1f1f] via-[#a94c1f] to-[#f4b942] p-6 text-white shadow-xl shadow-amber-500/20 sm:p-8"><div className="flex flex-col gap-6 lg:flex-row lg:items-end lg:justify-between"><div><p className="text-xs font-bold uppercase tracking-[.2em] text-amber-100">Lối vào nhanh</p><h2 className="mt-3 font-display text-3xl font-bold sm:text-4xl">Học theo cách của Ong</h2><p className="mt-3 max-w-2xl text-sm leading-6 text-amber-50">Mã 111 mở sẵn các lối tắt để bạn chuyển từ ý định sang hành động chỉ trong một chạm.</p></div><div className="rounded-2xl border border-white/20 bg-white/10 px-5 py-4 text-center backdrop-blur"><p className="text-xs uppercase tracking-widest text-amber-100">XP hiện tại</p><b className="mt-1 block text-3xl">{profile.xp.toLocaleString("vi-VN")}</b></div></div></section><section aria-label="Menu truy cập nhanh dành cho mã 111" className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{quick.map(({ icon: Icon, label, detail, view }) => <button key={view} onClick={() => onView(view)} className="group rounded-3xl border border-amber-200 bg-white p-5 text-left shadow-sm transition hover:-translate-y-0.5 hover:border-amber-400 hover:shadow-lg dark:border-amber-400/20 dark:bg-white/[.04]"><span className="grid h-11 w-11 place-items-center rounded-2xl bg-amber-100 text-amber-800 transition group-hover:bg-[#c62828] group-hover:text-white dark:bg-amber-400/15 dark:text-amber-200"><Icon className="h-5 w-5" /></span><b className="mt-4 block text-base">{label}</b><span className="mt-1 block text-sm leading-5 text-slate-500">{detail}</span><span className="mt-4 block text-xs font-bold uppercase tracking-widest text-[#c62828]">Mở ngay →</span></button>)}</section><section className="mt-5 grid gap-5 lg:grid-cols-2"><div className="panel p-6"><p className="text-xs font-bold uppercase tracking-widest text-amber-700 dark:text-amber-300">Trạng thái hôm nay</p><h2 className="mt-2 font-display text-2xl font-bold">{profile.studyActivity.length ? "Ong đang giữ nhịp rất tốt" : "Bắt đầu một nhịp học đầu tiên"}</h2><p className="mt-3 text-sm leading-6 text-slate-500">{profile.studyActivity.length ? `Đã ghi nhận ${profile.studyActivity.length} hoạt động trong hồ sơ học tập.` : "Chọn một lối vào nhanh ở trên để bắt đầu và lưu lại tiến trình."}</p></div><div className="panel p-6"><p className="text-xs font-bold uppercase tracking-widest text-amber-700 dark:text-amber-300">Quyền đặc biệt</p><div className="mt-4 grid gap-3 text-sm"><div className="flex items-center gap-3"><Check className="h-4 w-4 text-emerald-600" />Không bị giới hạn khóa tài khoản</div><div className="flex items-center gap-3"><Check className="h-4 w-4 text-emerald-600" />Truy cập nhanh các công cụ học tập</div><div className="flex items-center gap-3"><Check className="h-4 w-4 text-emerald-600" />Dữ liệu vẫn được lưu theo hồ sơ riêng</div></div></div></section></>; }
function AchievementProgressCards({ profile, config, onView }: { profile: ProfileState; config: AppConfig; onView: (view: View) => void }) { const nearest = nearestAchievements(profile, config, 3); const next = nearest[0]; const formatConditionValue = (type: string, value: number) => type === "studySeconds" ? `${Math.floor(value / 3600)}h ${Math.floor(value % 3600 / 60)}p` : value.toLocaleString("vi-VN"); return <section className="mb-5 grid gap-5 xl:grid-cols-[1.15fr_.85fr]" aria-label="Thành tích gần đạt"><div className="panel border-[#c62828]/20 bg-gradient-to-br from-[#fff8f5] to-white p-6 dark:border-red-300/20 dark:from-[#3a201d] dark:to-[#241b16]"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-[#c62828] dark:text-red-300">Thành tích tiếp theo</p><h2 className="mt-2 font-display text-2xl font-bold">{next ? `${next.icon} ${next.name}` : "Ong đã mở hết các mốc hiện có"}</h2>{next ? <><p className="mt-2 text-sm text-slate-600 dark:text-slate-300">{formatConditionValue(next.conditionType, next.currentValue)}/{formatConditionValue(next.conditionType, next.threshold)} · còn {formatConditionValue(next.conditionType, next.remaining)}</p><div className="mt-4 space-y-2">{next.conditions.map((condition) => <div key={condition.id} className="rounded-xl bg-white/70 px-3 py-2 text-xs dark:bg-black/10"><div className="flex items-center justify-between gap-3"><span className="font-semibold">{condition.met ? "☑" : "☐"} {condition.label}</span><span className="text-slate-500">{formatConditionValue(condition.type, condition.currentProgress)}/{formatConditionValue(condition.type, condition.targetProgress)}</span></div><div className="mt-1 h-1.5 overflow-hidden rounded-full bg-slate-200 dark:bg-white/10"><div className="h-full rounded-full bg-[#2e7d32]" style={{ width: `${condition.progressPercentage}%` }} /></div></div>)}</div></> : <p className="mt-2 text-sm text-slate-600 dark:text-slate-300">Mỗi dấu mốc là một câu chuyện Ong đã tự tạo ra.</p>}</div><span className="rounded-2xl bg-[#c62828] px-3 py-2 text-sm font-black text-white">{next ? `${next.progress}%` : "100%"}</span></div>{next && <><div className="mt-5 h-3 overflow-hidden rounded-full bg-red-100 dark:bg-red-950/50"><div className="h-full rounded-full bg-gradient-to-r from-[#c62828] to-[#2e7d32] transition-[width]" style={{ width: `${next.progress}%` }} /></div><p className="mt-3 text-sm leading-6 text-slate-600 dark:text-slate-300">{next.encouragement}</p><button className="primary-button mt-4" onClick={() => onView("achievements")}>Tiếp tục hành trình <ChevronRight className="h-4 w-4" /></button></>}</div><div className="panel p-6"><div className="flex items-center justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-green-700 dark:text-green-300">Gần đạt</p><h2 className="mt-2 font-display text-2xl font-bold">3 thành tích gần nhất</h2></div><Trophy className="h-6 w-6 text-[#c62828]" /></div>{nearest.length ? <div className="mt-5 space-y-3">{nearest.map((achievement) => <button key={achievement.id} onClick={() => onView("achievements")} className="w-full rounded-2xl border border-green-100 bg-green-50/60 p-3 text-left transition hover:-translate-y-0.5 hover:border-green-300 dark:border-green-300/15 dark:bg-green-950/20"><div className="flex items-center justify-between gap-3"><span className="min-w-0 truncate text-sm font-bold">{achievement.icon} {achievement.name}</span><span className="shrink-0 text-xs font-black text-[#c62828]">{achievement.currentValue}/{achievement.threshold}</span></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-white dark:bg-white/10"><div className="h-full rounded-full bg-[#2e7d32]" style={{ width: `${achievement.progress}%` }} /></div></button>)}</div> : <p className="mt-5 text-sm text-slate-500">Chưa có thành tích nào đang tiến tới từ dữ liệu hiện tại.</p>}</div></section> }

export function Dashboard({ account, profile, config, onView, onProfile }: { account: StudyAccount; profile: ProfileState; config: AppConfig; onView: (v: View) => void; onProfile: (profile: ProfileState, message?: string) => void }) { const selectedEmotion = profile.emotionTheme ?? "calm"; const stats = statsForProfile(profile); const todaySummary = dailyLearningSummary(profile); const achieved = computedAchievements(profile, config); const dayIndex = Math.floor(Date.now() / 86400000); const dailyEncouragements = config.encouragements.filter((entry) => entry.enabled); const dailyGreeting = dailyEncouragements.length ? dailyEncouragements[dayIndex % dailyEncouragements.length].text : "Ong hôm nay thế nào? Mình học một chút, vừa đủ để ngày mai nhẹ hơn."; const start = new Date(); start.setHours(0, 0, 0, 0); const todayActivities = profile.studyActivity.filter((activity) => new Date(activity.occurredAt) >= start); const todaySeconds = todayActivities.reduce((sum, activity) => sum + activity.durationSeconds, 0); const todayCards = todayActivities.filter((activity) => activity.kind === "flashcard").reduce((sum, activity) => sum + activity.quantity, 0); const todayQuizzes = todayActivities.filter((activity) => activity.kind === "quiz").length; const targetSeconds = 3 * 60 * 60; const timeLabel = todaySeconds >= 3600 ? `${Math.floor(todaySeconds / 3600)} giờ ${Math.floor(todaySeconds % 3600 / 60)} phút` : `${Math.floor(todaySeconds / 60)} phút`; return <><Heading eyebrow="Góc học tập của Ong" title={`Chào ${account.name.split(" ").at(-1)}!`} text={dailyGreeting} action={<button onClick={() => onView("focus")} className="primary-button"><Sparkles className="h-4 w-4" />Học 10 phút</button>} /><ExperienceStudio selected={selectedEmotion} onSelect={(emotion) => onProfile({ ...profile, emotionTheme: emotion }, "Đã đổi giao diện theo cảm xúc.")} profile={profile} onProfile={onProfile} onStartTwoMinutes={() => onView("pomodoro")} customContent={config.customContent} mascotStates={config.mascotStates} voiceLines={config.mascotVoiceLines} /><AchievementProgressCards profile={profile} config={config} onView={onView} /><section className="study-card mb-5 flex flex-col gap-4 p-5 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-slate-400">Hồ sơ thành viên</p><div className="mt-2 flex flex-wrap items-center gap-2"><h2 className="font-display text-2xl font-bold text-[#8e1b1b] dark:text-amber-200">{account.name}</h2><span className="rounded-full bg-amber-100 px-2.5 py-1 text-xs font-bold text-amber-800 dark:bg-amber-300/15 dark:text-amber-200">{account.role}</span></div><p className="mt-2 text-sm text-slate-500 dark:text-slate-300">Mã thành viên: <b className="text-slate-700 dark:text-white">{account.code}</b> · Cấp {profile.level} · {profile.xp.toLocaleString("vi-VN")} XP</p></div><div className="rounded-2xl bg-emerald-50 px-4 py-3 text-sm font-semibold text-emerald-800 dark:bg-emerald-300/10 dark:text-emerald-200">Tài khoản đang hoạt động</div></section><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat icon={Clock3} label="Thời gian học hôm nay" value={timeLabel} detail="Từ phiên đã ghi nhận" /><Stat icon={BookOpen} label="Flashcard đã học" value={todayCards} detail={`${stats.learnedCards} thẻ đã nhớ`} /><Stat icon={CircleHelp} label="Đề đã hoàn thành" value={todayQuizzes} detail={`${stats.completedQuizzes} đề toàn bộ`} /><Stat icon={Trophy} label="Dấu mốc đã mở" value={achieved.length} detail="mốc trong hành trình" /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.35fr_.85fr]"><section className="rounded-3xl bg-gradient-to-br from-[#6b4f35] via-[#c9822c] to-[#f4b942] p-6 text-white shadow-xl shadow-amber-500/20"><p className="text-xs font-bold uppercase tracking-[.18em] text-amber-100">Tiến trình hôm nay</p><h2 className="mt-3 font-display text-3xl font-bold">{timeLabel} / 3 giờ</h2><p className="mt-3 max-w-xl text-sm leading-6 text-amber-50">{todaySeconds >= targetSeconds ? "Ong đã hoàn thành nhịp học hôm nay. Lumi rất tự hào về nỗ lực của Ong!" : "Không cần hoàn hảo. Lumi đang ở đây và Ong chỉ cần tiến thêm một bước nhỏ!"}</p><div className="mt-9 flex items-center gap-4"><Progress value={todaySeconds / targetSeconds * 100} className="flex-1 bg-white/20" /><b>{Math.min(100, Math.round(todaySeconds / targetSeconds * 100))}%</b></div></section><section className="study-card p-5"><p className="text-xs font-bold uppercase tracking-[.16em] text-slate-400">Học tiếp một cách nhẹ nhàng</p><div className="mt-4 space-y-2"><Quick icon={BrainCircuit} text="Tạo nội dung từ dữ liệu AI" click={() => onView("ai-import")} /><Quick icon={BookOpen} text="Ôn Flashcard chưa chắc" click={() => onView("focus")} /><Quick icon={History} text="Khám phá câu chuyện lịch sử" click={() => onView("museum")} /></div></section></div><section className="study-card mt-5 p-5" aria-label="Tổng kết cuối ngày"><p className="text-xs font-bold uppercase tracking-[.16em] text-[#c62828]">Lumi tổng kết nhẹ nhàng</p><h2 className="mt-2 font-display text-2xl font-bold">Hôm nay Ong đã làm được {todaySummary.activityCount} điều</h2><div className="mt-4 grid gap-2 sm:grid-cols-2"><p className="rounded-xl bg-[#fff4f1] p-3 text-sm font-semibold text-[#8e1b1b] dark:bg-red-950/30 dark:text-red-100">🍅 {todaySummary.started ? "Ong đã bắt đầu." : "Ong chưa bắt đầu — mình thử 5 phút cũng được."}</p><p className="rounded-xl bg-[#eff9ef] p-3 text-sm font-semibold text-[#245c2b] dark:bg-green-950/30 dark:text-green-100">🧠 {todaySummary.deepCount ? `Ong đã hiểu thêm ${todaySummary.deepCount} điều.` : "Mỗi lần nhìn lại cũng là một bước hiểu hơn."}</p><p className="rounded-xl bg-[#fff4f1] p-3 text-sm font-semibold text-[#8e1b1b] dark:bg-red-950/30 dark:text-red-100">🔧 {todaySummary.correctedMistakes ? `Ong đã sửa ${todaySummary.correctedMistakes} lỗi.` : "Chưa có lỗi được ghi nhận hôm nay."}</p><p className="rounded-xl bg-[#eff9ef] p-3 text-sm font-semibold text-[#245c2b] dark:bg-green-950/30 dark:text-green-100">🌱 {todaySummary.xpEarned > 0 ? `Ong đã nhận ${todaySummary.xpEarned} XP.` : "Không sao nếu hôm nay chưa học; XP không bị trừ."}</p></div></section></>; }

function Stat({ icon: Icon, label, value, detail }: { icon: typeof Award; label: string; value: string | number; detail: string }) { const tone = label.includes("Thời gian") ? "semantic-info" : label.includes("Flashcard") ? "semantic-positive" : label.includes("Đề") ? "semantic-special" : "semantic-challenge"; return <div className="study-card p-5"><div className="flex justify-between gap-3"><span className={cn("grid h-11 w-11 place-items-center rounded-2xl", tone)}><Icon className="h-5 w-5" /></span><small className="pt-1 text-right text-slate-400">{detail}</small></div><b className="mt-5 block text-3xl text-slate-950 dark:text-white">{typeof value === "number" ? value.toLocaleString("vi-VN") : value}</b><p className="mt-1 text-sm text-slate-500">{label}</p></div>; }
function Quick({ icon: Icon, text, click }: { icon: typeof Trophy; text: string; click: () => void }) { return <button onClick={click} className="flex w-full items-center gap-3 rounded-xl border border-slate-100 p-3 text-left hover:border-amber-200 hover:bg-amber-50/40 dark:border-white/10 dark:hover:bg-amber-400/5"><Icon className="h-4 w-4 text-amber-700" /><span className="flex-1 text-sm font-bold">{text}</span><ChevronRight className="h-4 w-4 text-slate-400" /></button>; }
function Studio({ profile, onProfile, onView, token }: { profile: ProfileState; onProfile: (p: ProfileState, m?: string) => void; onView: (v: View) => void; token: string }) { const [tab, setTab] = useState<"cards" | "quiz" | "both">("cards"); const [title, setTitle] = useState(""); const [subject, setSubject] = useState(""); const [purpose, setPurpose] = useState(""); const [topic, setTopic] = useState(""); const [source, setSource] = useState(""); const [schoolLevel, setSchoolLevel] = useState(""); const [difficulty, setDifficulty] = useState<"Cơ bản" | "Trung bình" | "Nâng cao">("Trung bình"); const [requirements, setRequirements] = useState(""); const [sourceFileName, setSourceFileName] = useState(""); const [sourceFileContent, setSourceFileContent] = useState(""); const [sourceFileDataUrl, setSourceFileDataUrl] = useState(""); const [sourceFileContentType, setSourceFileContentType] = useState<"text/plain" | "text/markdown" | "application/pdf">(); const generateFromDocument = trpc.study.ai.generateFromDocument.useMutation({ onSuccess: (data) => { setResult(data.content); toast.success("AI đã tạo JSON từ tài liệu."); }, onError: (error) => toast.error(error.message) }); const [questionCount, setQuestionCount] = useState(10); const [durationMinutes, setDurationMinutes] = useState(20); const [multipleRatio, setMultipleRatio] = useState(60); const [booleanRatio, setBooleanRatio] = useState(20); const [answerOptionCount, setAnswerOptionCount] = useState(4); const [includeAnswerKey, setIncludeAnswerKey] = useState(true); const [result, setResult] = useState(""); const [promptDraft, setPromptDraft] = useState(""); const shortRatio = Math.max(0, 100 - multipleRatio - booleanRatio); const generatedPrompt = tab === "cards" ? `Tạo tối đa 27 Flashcard tiếng Việt cho môn ${subject || "[môn học]"}, mục đích ${purpose || "[mục đích học]"}, lớp ${schoolLevel || "[lớp học]"}, chủ đề ${topic || "[chủ đề]"}, mức độ ${difficulty}. Yêu cầu: ${requirements || "[yêu cầu]"}. Dựa vào: ${sourceFileContent || source || (sourceFileName ? `tệp ${sourceFileName}` : "[tài liệu]")}. Chỉ trả về JSON: [{"front":"câu hỏi","back":"đáp án"}].` : `Tạo đề kiểm tra ${questionCount} câu, thời gian ${durationMinutes} phút, môn ${subject || "[môn học]"}, lớp ${schoolLevel || "[lớp học]"}, chủ đề ${topic || "[chủ đề]"}, mức độ ${difficulty}. Tỷ lệ: trắc nghiệm ${multipleRatio}%, đúng/sai ${booleanRatio}%, trả lời ngắn ${shortRatio}%. Mỗi câu trắc nghiệm có ${answerOptionCount} lựa chọn. ${includeAnswerKey ? "Bao gồm đáp án và giải thích." : "Không đưa đáp án mẫu, chỉ tạo câu hỏi."} Yêu cầu: ${requirements || "[yêu cầu]"}. Chỉ trả về JSON {"questions":[{"type":"multiple|boolean|short","prompt":"...","options":["A","B","C","D"],"answer":"...","explanation":"..."}]}`;
  useEffect(() => { setPromptDraft(generatedPrompt); }, [generatedPrompt]); const prompt = promptDraft || generatedPrompt; const generate = () => { if (!subject) return toast.error("Hãy nhập môn học trước."); generateFromDocument.mutate({ token, mode: tab, prompt, fileName: sourceFileName || undefined, contentType: sourceFileContentType, dataUrl: sourceFileDataUrl || undefined }); }; const create = () => { if (!title || !subject) return toast.error("Hãy nhập tên và môn học."); if (tab === "both") { const cards = parseCards(result).slice(0, 27); const questions = parseQuestions(result).slice(0, Math.max(1, questionCount)); const cardValidation = validateGeneratedCards(cards); const questionValidation = validateGeneratedQuestions(questions); if (!cardValidation.valid || !questionValidation.valid) return toast.error([...cardValidation.errors, ...questionValidation.errors].join(" ")); if (cardValidation.warnings.length || questionValidation.warnings.length) toast.warning([...cardValidation.warnings, ...questionValidation.warnings].join(" ")); const createdAt = new Date().toISOString(); const set: FlashcardSet = { id: uid(), title: `${title} · Flashcard`, subject, topic, difficulty, createdAt, studyCount: 0, cards }; const quiz: Quiz = { id: uid(), title: `${title} · Đề kiểm tra`, subject, topic, difficulty, durationMinutes: Math.max(1, durationMinutes), createdAt, questions }; onProfile({ ...profile, flashcardSets: [set, ...profile.flashcardSets], quizzes: [quiz, ...profile.quizzes] }, `Đã tạo ${cards.length} Flashcard và đề ${questions.length} câu.`); onView("flashcards"); return; } if (tab === "cards") { const cards = parseCards(result).slice(0, 27); const validation = validateGeneratedCards(cards); if (!validation.valid) return toast.error(validation.errors.join(" ")); if (validation.warnings.length) toast.warning(validation.warnings.join(" ")); const set: FlashcardSet = { id: uid(), title, subject, topic, difficulty, createdAt: new Date().toISOString(), studyCount: 0, cards }; onProfile({ ...profile, flashcardSets: [set, ...profile.flashcardSets] }, `Đã tạo ${cards.length} Flashcard.`); onView("flashcards"); } else { const questions = parseQuestions(result).slice(0, Math.max(1, questionCount)); const validation = validateGeneratedQuestions(questions); if (!validation.valid) return toast.error(validation.errors.join(" ")); if (validation.warnings.length) toast.warning(validation.warnings.join(" ")); const quiz: Quiz = { id: uid(), title, subject, topic, difficulty, durationMinutes: Math.max(1, durationMinutes), createdAt: new Date().toISOString(), questions }; onProfile({ ...profile, quizzes: [quiz, ...profile.quizzes] }, `Đã tạo đề ${questions.length} câu.`); onView("quizzes"); } };
  return <><Heading eyebrow="AI Studio" title="Biến tài liệu thành trải nghiệm học tập" text="Sao chép prompt chuẩn sang AI bên ngoài, sau đó dán kết quả JSON để tạo dữ liệu học cho riêng tài khoản này." /><div className="grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><section className="panel p-5"><div className="flex rounded-xl bg-slate-100 p-1 dark:bg-white/5"><button className={cn("tab", tab === "cards" && "selected")} onClick={() => setTab("cards")}>Flashcard</button><button className={cn("tab", tab === "quiz" && "selected")} onClick={() => setTab("quiz")}>Đề kiểm tra</button><button className={cn("tab", tab === "both" && "selected")} onClick={() => setTab("both")}>Cả hai</button></div><div className="mt-5 grid gap-4 sm:grid-cols-2"><Input label="Tên bộ / đề" value={title} set={setTitle} placeholder="Ví dụ: Khí lý tưởng" /><Input label="Môn học" value={subject} set={setSubject} placeholder="Ví dụ: Vật lí 12" /><Input label="Mục đích học" value={purpose} set={setPurpose} placeholder="Ví dụ: ôn thi học kỳ, hiểu bản chất" /><Input label="Chủ đề" value={topic} set={setTopic} placeholder="Ví dụ: Định luật Charles" /><Input label="Lớp học" value={schoolLevel} set={setSchoolLevel} placeholder="Ví dụ: 12" /><label className="block text-sm font-bold">Mức độ<select value={difficulty} onChange={(e) => setDifficulty(e.target.value as typeof difficulty)} className="input"><option>Cơ bản</option><option>Trung bình</option><option>Nâng cao</option></select></label>{tab !== "cards" && <><label className="block text-sm font-bold">Số câu<input type="number" min={1} max={100} value={questionCount} onChange={(e) => setQuestionCount(Number(e.target.value))} className="input" /></label><label className="block text-sm font-bold">Thời gian (phút)<input type="number" min={1} max={180} value={durationMinutes} onChange={(e) => setDurationMinutes(Number(e.target.value))} className="input" /></label></>}</div><label className="mt-4 block text-sm font-bold">Yêu cầu chi tiết<textarea value={requirements} onChange={(e) => setRequirements(e.target.value)} rows={3} className="textarea" placeholder="Ví dụ: ưu tiên khái niệm trọng tâm, có ví dụ thực tế…" /></label><label className="mt-4 block text-sm font-bold">Tài liệu hoặc yêu cầu<textarea value={source} onChange={(e) => setSource(e.target.value)} rows={6} className="textarea" placeholder="Dán tài liệu hoặc yêu cầu học tập. Nội dung này dùng để tạo prompt." /></label><label className="mt-3 block text-sm font-bold">Tải tài liệu TXT, MD hoặc PDF<input type="file" accept=".txt,.md,.pdf,text/plain,text/markdown,application/pdf" className="input mt-1" onChange={async (e) => { const file = e.target.files?.[0]; if (!file) return; setSourceFileName(file.name); const contentType = file.type === "application/pdf" || file.name.toLowerCase().endsWith(".pdf") ? "application/pdf" : file.name.toLowerCase().endsWith(".md") ? "text/markdown" : "text/plain"; setSourceFileContentType(contentType); const dataUrl = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(reader.error); reader.readAsDataURL(file); }); setSourceFileDataUrl(dataUrl); if (file.type === "text/plain" || file.name.endsWith(".md") || file.name.endsWith(".txt")) { const text = await file.text(); setSourceFileContent(text.slice(0, 120000)); setSource(text.slice(0, 120000)); } else { setSourceFileContent(`Tệp PDF đính kèm: ${file.name}. Hãy sử dụng nội dung tệp PDF này làm nguồn chính khi biên soạn.`); } }} /><small className="mt-1 block text-xs text-slate-500">{sourceFileName ? `Đã chọn: ${sourceFileName}` : "TXT/MD được đọc trực tiếp; PDF được giữ làm nguồn tài liệu để gửi cùng yêu cầu."}</small></label>{tab !== "cards" && <div className="mt-4 grid gap-4 sm:grid-cols-3"><Input label="Trắc nghiệm %" value={String(multipleRatio)} set={(value) => setMultipleRatio(Math.min(100, Math.max(0, Number(value) || 0)))} placeholder="60" /><Input label="Đúng/sai %" value={String(booleanRatio)} set={(value) => setBooleanRatio(Math.min(100 - multipleRatio, Math.max(0, Number(value) || 0)))} placeholder="20" /><div className="rounded-xl bg-slate-50 p-3 text-xs font-bold text-slate-500 dark:bg-white/5">Trả lời ngắn<br /><b className="text-lg text-amber-700">{shortRatio}%</b></div><label className="block text-sm font-bold">Số lựa chọn<input type="number" min={2} max={6} value={answerOptionCount} onChange={(e) => setAnswerOptionCount(Math.min(6, Math.max(2, Number(e.target.value) || 2)))} className="input" /></label><label className="flex items-center gap-2 text-sm font-bold"><input type="checkbox" checked={includeAnswerKey} onChange={(e) => setIncludeAnswerKey(e.target.checked)} />Kèm đáp án mẫu</label></div>}</section><section className="rounded-3xl bg-gradient-to-br from-[#2d211a] via-[#5c4028] to-[#9a6a2f] p-5 text-white"><p className="text-xs font-bold uppercase tracking-widest text-amber-200">Bước 1 · Prompt chuẩn</p><textarea aria-label="Prompt AI có thể chỉnh sửa" value={promptDraft} onChange={(e) => setPromptDraft(e.target.value)} rows={10} className="mt-4 w-full rounded-2xl bg-black/20 p-4 text-sm leading-6 text-amber-50/90 outline-none ring-1 ring-white/10" /><div className="mt-4 grid gap-2 sm:grid-cols-2"><button onClick={() => { setPromptDraft(generatedPrompt); toast.success("Đã tạo lại prompt từ biểu mẫu."); }} className="rounded-xl bg-amber-300 py-3 text-sm font-bold text-slate-950">Tạo lại prompt</button><button onClick={() => navigator.clipboard.writeText(promptDraft || generatedPrompt).then(() => toast.success("Đã sao chép prompt."))} className="rounded-xl bg-amber-200 py-3 text-sm font-bold text-slate-950">Sao chép prompt</button><button disabled={generateFromDocument.isPending} onClick={generate} className="rounded-xl bg-amber-300 py-3 text-sm font-bold text-slate-950">{generateFromDocument.isPending ? "Đang tạo…" : "Tạo từ tài liệu"}</button></div></section></div><section className="panel mt-5 p-5"><p className="text-xs font-bold uppercase tracking-widest text-slate-400">Bước 3 · Nhập kết quả AI</p><textarea value={result} onChange={(e) => setResult(e.target.value)} rows={9} className="textarea mt-3 font-mono text-xs" placeholder={tab === "cards" ? '[{"front":"Câu hỏi","back":"Đáp án"}]' : '{"questions":[{"type":"multiple","prompt":"...","options":["A","B"],"answer":"A"}]}' } /><button onClick={create} className="primary-button mt-4"><Sparkles className="h-4 w-4" />Tạo {tab === "cards" ? "Flashcard" : tab === "quiz" ? "đề kiểm tra" : "cả hai"}</button><span className="ml-3 text-xs text-slate-500">{tab === "cards" ? "Tối đa 27 thẻ mỗi lượt; không giới hạn số bộ." : tab === "quiz" ? "Hỗ trợ trắc nghiệm, đúng/sai và trả lời ngắn." : "Tạo đồng thời tối đa 27 Flashcard và một đề kiểm tra."}</span></section></>;
}
function Input({ label, value, set, placeholder }: { label: string; value: string; set: (x: string) => void; placeholder: string }) { return <label className="block text-sm font-bold">{label}<input value={value} onChange={(e) => set(e.target.value)} placeholder={placeholder} className="input" /></label>; }
function Cards({ profile, config, onProfile }: { profile: ProfileState; config: AppConfig; onProfile: (p: ProfileState, m?: string) => void }) { const [id, setId] = useState(profile.flashcardSets[0]?.id); const [index, setIndex] = useState(0); const [flipped, setFlipped] = useState(false); const [studyMode, setStudyMode] = useState<"flip" | "choice" | "write" | "rapid">("flip"); const [writeAnswer, setWriteAnswer] = useState(""); const [sessionStats, setSessionStats] = useState({ total: 0, known: 0, learning: 0, xp: 0 }); const [showReport, setShowReport] = useState(false); const [rapidSeconds, setRapidSeconds] = useState(0); const [rapidExpired, setRapidExpired] = useState(false); const rapidLimitSeconds = 60; useEffect(() => { if (studyMode !== "rapid") { setRapidSeconds(0); setRapidExpired(false); return; } const started = Date.now(); const timer = window.setInterval(() => { const elapsed = Math.floor((Date.now() - started) / 1000); setRapidSeconds(elapsed); if (elapsed >= rapidLimitSeconds) { setRapidExpired(true); window.clearInterval(timer); } }, 1000); return () => window.clearInterval(timer); }, [studyMode]); const [setQuery, setSetQuery] = useState(""); const [setDifficulty, setSetDifficulty] = useState("all"); const [setDateFilter, setSetDateFilter] = useState("all"); const filteredSets = profile.flashcardSets.filter((x) => { const matchesText = !setQuery || `${x.title} ${x.subject} ${x.topic}`.toLowerCase().includes(setQuery.toLowerCase()); const matchesDifficulty = setDifficulty === "all" || x.difficulty === setDifficulty; const createdAt = new Date(x.createdAt).getTime(); const cutoff = Date.now() - (setDateFilter === "7d" ? 7 : 30) * 86400000; const matchesDate = setDateFilter === "all" || (Number.isFinite(createdAt) && createdAt >= cutoff); return matchesText && matchesDifficulty && matchesDate; }); const set = profile.flashcardSets.find((x) => x.id === id) ?? filteredSets[0] ?? profile.flashcardSets[0]; if (!set) return <><Heading eyebrow="Flashcard" title="Không gian ghi nhớ chủ động" text="Tạo bộ học đầu tiên trong AI Studio, sau đó quay lại đây để lật thẻ và theo dõi tiến độ." /><Empty icon={BookOpen} title="Chưa có bộ Flashcard" text="AI Studio sẽ chuyển dữ liệu JSON thành bộ học cho tài khoản này." /></>; const card = set.cards[index] ?? set.cards[0]; const known = set.cards.filter((x) => x.status === "known").length; const mark = (status: "known" | "learning") => { setSessionStats((previous) => ({ total: previous.total + 1, known: previous.known + (status === "known" ? 1 : 0), learning: previous.learning + (status === "learning" ? 1 : 0), xp: previous.xp + (status === "known" ? 8 : 2) })); const sets = profile.flashcardSets.map((s) => s.id === set.id ? { ...s, studyCount: s.studyCount + 1, cards: s.cards.map((c, i) => i === index ? { ...c, status } : c) } : s); const occurredAt = new Date().toISOString(); const xpEarned = status === "known" ? 8 : 2; const reward = applyStudyActivityRewards({ ...profile, flashcardSets: sets }, { id: `flashcard-${set.id}-${card.id}-${occurredAt.slice(0, 10)}`, occurredAt, kind: "flashcard", quantity: 1, durationSeconds: 0, xpEarned }, config); onProfile(reward.profile, status === "known" ? `+${xpEarned} XP · Đã ghi nhận thẻ nhớ${reward.newlyUnlocked.length ? ` · Mở khóa ${reward.newlyUnlocked.length} thành tích` : ""}.` : "Đã đánh dấu cần ôn lại."); }; const normalizeAnswer = (value: string) => value.trim().replace(/\s+/g, " ").toLocaleLowerCase("vi"); const answerChoice = (choice: string) => { setFlipped(true); mark(normalizeAnswer(choice) === normalizeAnswer(card.back) ? "known" : "learning"); }; const answerWrite = () => { if (!writeAnswer.trim()) return; setFlipped(true); mark(normalizeAnswer(writeAnswer) === normalizeAnswer(card.back) ? "known" : "learning"); setWriteAnswer(""); }; const restartSession = () => { setSessionStats({ total: 0, known: 0, learning: 0, xp: 0 }); setShowReport(false); setIndex(0); setFlipped(false); setWriteAnswer(""); setRapidSeconds(0); setRapidExpired(false); }; const renameSet = () => { const title = window.prompt("Tên mới cho bộ Flashcard", set.title)?.trim(); if (!title) return; onProfile({ ...profile, flashcardSets: profile.flashcardSets.map((item) => item.id === set.id ? { ...item, title } : item) }, "Đã đổi tên bộ Flashcard."); }; const copySet = () => { const clone = { ...set, id: uid(), title: `${set.title} · Bản sao`, createdAt: new Date().toISOString(), studyCount: 0, cards: set.cards.map((card) => ({ ...card, id: uid(), status: "new" as const })) }; onProfile({ ...profile, flashcardSets: [clone, ...profile.flashcardSets] }, "Đã sao chép bộ Flashcard."); setId(clone.id); setIndex(0); }; const deleteSet = () => { if (!window.confirm(`Xóa bộ “${set.title}”?`)) return; const remaining = profile.flashcardSets.filter((item) => item.id !== set.id); onProfile({ ...profile, flashcardSets: remaining }, "Đã xóa bộ Flashcard."); setId(remaining[0]?.id); setIndex(0); }; const createQuizFromSet = () => { const quiz = createQuizFromFlashcardSet(set); onProfile({ ...profile, quizzes: [quiz, ...profile.quizzes] }, `Đã tạo đề ôn tập ${quiz.questions.length} câu từ bộ Flashcard.`); };
  return <><Heading eyebrow="Flashcard" title="Học bằng cách chủ động nhớ lại" text="Lật thẻ để kiểm tra trí nhớ, sau đó đánh dấu đã nhớ hoặc cần ôn lại." /><div className="grid gap-5 xl:grid-cols-[280px_1fr]"><aside className="panel p-4"><b className="font-display text-lg">Bộ của bạn</b><input aria-label="Tìm bộ Flashcard" value={setQuery} onChange={(e) => setSetQuery(e.target.value)} placeholder="Tìm theo tên, môn, chủ đề" className="input mt-3" /><select aria-label="Lọc độ khó Flashcard" value={setDifficulty} onChange={(e) => setSetDifficulty(e.target.value)} className="input mt-2"><option value="all">Mọi độ khó</option><option>Cơ bản</option><option>Trung bình</option><option>Nâng cao</option></select><select aria-label="Lọc ngày Flashcard" value={setDateFilter} onChange={(e) => setSetDateFilter(e.target.value)} className="input mt-2"><option value="all">Mọi ngày</option><option value="7d">7 ngày gần đây</option><option value="30d">30 ngày gần đây</option></select><div className="mt-4 space-y-2">{filteredSets.map((x) => <button key={x.id} onClick={() => { setId(x.id); setIndex(0); setFlipped(false); }} className={cn("w-full rounded-xl p-3 text-left", x.id === set.id ? "bg-amber-50 text-amber-900 dark:bg-amber-400/10 dark:text-amber-100" : "hover:bg-slate-50 dark:hover:bg-white/5")}><b className="block truncate text-sm">{x.title}</b><small className="text-xs text-slate-500">{x.cards.length} thẻ · {x.subject}</small></button>)}</div><div className="mt-4 grid grid-cols-2 gap-2 sm:grid-cols-4"><button aria-label="Đổi tên bộ Flashcard" onClick={renameSet} className="secondary-button px-2 text-xs">Đổi tên</button><button aria-label="Sao chép bộ Flashcard" onClick={copySet} className="secondary-button px-2 text-xs">Sao chép</button><button aria-label="Xóa bộ Flashcard" onClick={deleteSet} className="secondary-button px-2 text-xs text-rose-700">Xóa</button><button aria-label="Tạo đề từ bộ Flashcard" onClick={createQuizFromSet} className="secondary-button px-2 text-xs">Tạo đề</button></div></aside><section><div className="panel p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex flex-wrap gap-2" role="tablist" aria-label="Chế độ học Flashcard"><button aria-selected={studyMode === "flip"} onClick={() => setStudyMode("flip")} className={cn("secondary-button px-3 text-xs", studyMode === "flip" && "bg-amber-100 text-amber-900")}>Lật thẻ</button><button aria-selected={studyMode === "choice"} onClick={() => setStudyMode("choice")} className={cn("secondary-button px-3 text-xs", studyMode === "choice" && "bg-amber-100 text-amber-900")}>Trắc nghiệm</button><button aria-selected={studyMode === "write"} onClick={() => setStudyMode("write")} className={cn("secondary-button px-3 text-xs", studyMode === "write" && "bg-amber-100 text-amber-900")}>Tự viết</button><button aria-selected={studyMode === "rapid"} onClick={() => setStudyMode("rapid")} className={cn("secondary-button px-3 text-xs", studyMode === "rapid" && "bg-amber-100 text-amber-900")}>Tốc độ</button></div><div className="flex justify-between gap-4"><span><p className="text-xs font-bold uppercase tracking-widest text-amber-700">{set.subject}</p><h2 className="mt-1 font-display text-2xl font-bold">{set.title}</h2></span><b className="text-sm">{index + 1}/{set.cards.length}</b></div></div><Progress value={known / set.cards.length * 100} className="mt-4" /></div>{studyMode === "choice" && <div className="mt-4 grid gap-2 sm:grid-cols-2"><p className="sm:col-span-2 text-sm font-bold text-amber-800">Chọn đáp án đúng:</p>{Array.from(new Set([card.back, ...set.cards.filter((item) => item.id !== card.id).map((item) => item.back)])).slice(0, 4).map((choice) => <button key={choice} onClick={() => answerChoice(choice)} className="secondary-button text-left">{choice}</button>)}</div>}{studyMode === "rapid" && <div className="mt-4 flex items-center justify-between rounded-xl bg-amber-50 px-4 py-3 text-sm font-bold text-amber-900 dark:bg-amber-400/10 dark:text-amber-100"><span>Phiên tốc độ · {rapidSeconds}/{rapidLimitSeconds}s</span><span>{rapidExpired ? "Đã hết giờ" : `Đã chấm ${sessionStats.total} thẻ`}</span></div>}{studyMode === "write" && <div className="mt-4 flex gap-2"><input aria-label="Câu trả lời tự viết" value={writeAnswer} onChange={(e) => setWriteAnswer(e.target.value)} placeholder="Nhập đáp án trước khi kiểm tra" className="input" /><button onClick={answerWrite} className="secondary-button">Kiểm tra</button></div>}<button onClick={() => setFlipped(!flipped)} className="mt-5 min-h-[340px] w-full rounded-[2rem] bg-gradient-to-br from-[#4b2e1f] via-[#805b32] to-[#b67b2d] p-8 text-left text-white shadow-xl shadow-amber-500/20"><p className="text-xs font-bold uppercase tracking-widest text-amber-200">{flipped ? "Đáp án" : "Câu hỏi"}</p><p className="mt-14 font-display text-3xl font-bold leading-relaxed">{flipped ? card.back : card.front}</p><p className="mt-12 text-sm text-amber-100">Nhấn vào thẻ để lật.</p></button><div className="mt-5 flex flex-wrap justify-center gap-2"><button onClick={() => { setIndex((index - 1 + set.cards.length) % set.cards.length); setFlipped(false); }} className="icon-button"><ChevronLeft className="h-5 w-5" /></button><button disabled={rapidExpired} onClick={() => mark("learning")} className="secondary-button text-rose-600 disabled:opacity-50">Cần ôn lại</button><button onClick={() => setFlipped(!flipped)} className="secondary-button">Lật thẻ</button><button disabled={rapidExpired} onClick={() => mark("known")} className="rounded-xl bg-emerald-500 px-4 py-2.5 text-sm font-bold text-white disabled:opacity-50">Đã nhớ</button><button onClick={() => { setIndex((index + 1) % set.cards.length); setFlipped(false); }} className="icon-button"><ChevronRight className="h-5 w-5" /></button><button onClick={() => setShowReport(true)} className="secondary-button">{rapidExpired ? "Xem kết quả tốc độ" : "Báo cáo phiên"}</button></div>{showReport && <div role="status" aria-live="polite" className="session-complete mt-4 rounded-2xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-950 dark:border-amber-400/20 dark:bg-amber-400/10 dark:text-amber-100"><b className="font-display text-lg">Báo cáo phiên học</b><p className="mt-2">Đã chấm {sessionStats.total} thẻ · Đúng/đã nhớ {sessionStats.known} · Cần ôn lại {sessionStats.learning} · +{sessionStats.xp} XP.</p><p className="mt-1 text-xs opacity-80">Phần thưởng mảnh ghép và thành tích được cập nhật theo profile sau mỗi lần chấm.</p><button onClick={restartSession} className="secondary-button mt-3">Học lại phiên</button></div>}</section></div></>;
}
function normalizeQuizAnswer(value: string) { return value.normalize("NFKC").trim().replace(/[.,!?;:()[\]{}"'“”‘’]/g, "").replace(/\s+/g, " ").toLocaleLowerCase("vi"); }
function quizAnswerMatches(question: QuizQuestion, given: string) { const actual = normalizeQuizAnswer(given); const expected = normalizeQuizAnswer(question.answer); if (!actual || !expected) return false; if (actual === expected) return true; const actualNumbers = actual.match(/\d+/g); const expectedNumbers = expected.match(/\d+/g); if (actualNumbers?.length && expectedNumbers?.length && actualNumbers.join(" ") === expectedNumbers.join(" ")) return true; return !question.options?.length && actual.length >= 2 && (expected.endsWith(actual) || actual.endsWith(expected)); }
function Quizzes({ profile, config, onProfile }: { profile: ProfileState; config: AppConfig; onProfile: (p: ProfileState, m?: string) => void }) { const [active, setActive] = useState<Quiz | null>(null); const [answers, setAnswers] = useState<Record<string, string>>({}); const [index, setIndex] = useState(0); const [result, setResult] = useState<number | null>(null); if (!profile.quizzes.length && !active) return <><Heading eyebrow="Đề kiểm tra" title="Tự đánh giá sau mỗi chặng học" text="Tạo đề từ AI Studio. Kết quả và XP được giữ riêng cho tài khoản hiện tại." /><Empty icon={CircleHelp} title="Chưa có đề kiểm tra" text="Dùng AI Studio để tạo đề trắc nghiệm, đúng/sai hoặc trả lời ngắn." /></>; if (!active) return <><Heading eyebrow="Đề kiểm tra" title="Chọn một đề để bắt đầu" text="Mỗi lần hoàn thành đề sẽ được tính XP và cập nhật thống kê học tập." /><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{profile.quizzes.map((q) => <button key={q.id} onClick={() => { setActive(q); setAnswers({}); setIndex(0); setResult(null); }} className="panel p-5 text-left transition hover:-translate-y-1 hover:border-amber-200"><CircleHelp className="h-6 w-6 text-amber-700" /><p className="mt-5 text-xs font-bold uppercase tracking-widest text-amber-700">{q.subject} · {q.difficulty}</p><h2 className="mt-2 font-display text-xl font-bold">{q.title}</h2><p className="mt-5 text-xs text-slate-500">{q.questions.length} câu · {q.durationMinutes} phút</p></button>)}</div></>; const question = active.questions[index]; const finish = () => { const correct = active.questions.filter((q) => quizAnswerMatches(q, answers[q.id] ?? "")).length; setResult(correct); const xp = 20 + correct * 8; const next = { ...profile, xp: profile.xp + xp, attempts: [{ id: uid(), quizId: active.id, completedAt: new Date().toISOString(), correct, total: active.questions.length, accuracy: Math.round(correct / active.questions.length * 100), durationSeconds: 0 }, ...profile.attempts] }; next.level = levelForXp(next.xp); onProfile(next, `Đã nộp bài · +${xp} XP.`); };
  if (result !== null) return <><Heading eyebrow="Kết quả học tập" title={`${Math.round(result / active.questions.length * 100)}% chính xác`} text={`Bạn trả lời đúng ${result}/${active.questions.length} câu. Xem lại đáp án để củng cố kiến thức.`} action={<button onClick={() => setActive(null)} className="secondary-button">Danh sách đề</button>} /><div className="space-y-3">{active.questions.map((q, i) => <div key={q.id} className={cn("panel p-4", quizAnswerMatches(q, answers[q.id] ?? "") ? "border-emerald-200" : "border-rose-200")}><b>{i + 1}. {q.prompt}</b><p className="mt-2 text-sm text-slate-500">Đáp án: <b>{q.answer}</b>{q.explanation ? ` · ${q.explanation}` : ""}</p></div>)}</div></>; return <><Heading eyebrow={`${active.subject} · ${active.difficulty}`} title={active.title} text={`${active.questions.length} câu hỏi · ${active.durationMinutes} phút`} action={<button onClick={() => setActive(null)} className="secondary-button">Danh sách đề</button>} /><div className="grid gap-5 xl:grid-cols-[1fr_250px]"><section className="panel p-6"><div className="flex justify-between"><span className="rounded-full bg-amber-50 px-3 py-1 text-xs font-bold text-amber-800">Câu {index + 1}/{active.questions.length}</span><span className="flex items-center gap-2 font-mono font-bold"><Clock3 className="h-4 w-4 text-rose-500" />20:00</span></div><h2 className="mt-10 font-display text-2xl font-bold leading-relaxed">{question.prompt}</h2><Answer question={question} value={answers[question.id] ?? ""} set={(value) => setAnswers((previous) => ({ ...previous, [question.id]: value }))} /><div className="mt-8 flex justify-between"><button onClick={() => setIndex(Math.max(0, index - 1))} className="secondary-button"><ChevronLeft className="h-4 w-4" />Trước</button>{index === active.questions.length - 1 ? <button onClick={finish} className="primary-button">Nộp bài</button> : <button onClick={() => setIndex(index + 1)} className="primary-button">Tiếp<ChevronRight className="h-4 w-4" /></button>}</div></section><aside className="panel p-4"><p className="text-xs font-bold uppercase tracking-widest text-slate-400">Điều hướng câu hỏi</p><div className="mt-4 grid grid-cols-5 gap-2">{active.questions.map((q, i) => <button key={q.id} onClick={() => setIndex(i)} className={cn("grid h-9 place-items-center rounded-lg text-sm font-bold", i === index ? "bg-amber-600 text-white" : answers[q.id] ? "bg-amber-50 text-amber-800" : "bg-slate-100 text-slate-500 dark:bg-white/5")}>{i + 1}</button>)}</div><button className="mt-5 inline-flex items-center gap-2 text-xs font-bold text-amber-600"><Flag className="h-4 w-4" />Đánh dấu câu</button></aside></div></>;
}
function Answer({ question, value, set }: { question: QuizQuestion; value: string; set: (x: string) => void }) { if (question.type === "short") return <textarea value={value} onChange={(e) => set(e.target.value)} rows={4} className="textarea" placeholder="Nhập câu trả lời…" />; const options = question.type === "boolean" ? ["Đúng", "Sai"] : question.options ?? []; return <div className="mt-6 grid gap-3">{options.map((x) => <button key={x} onClick={() => set(x)} className={cn("rounded-xl border p-4 text-left text-sm font-bold", value === x ? "border-amber-400 bg-amber-50 text-amber-900 dark:bg-amber-400/10 dark:text-amber-100" : "border-slate-200 dark:border-white/10")}>{x}</button>)}</div>; }
function Achievements({ profile, config }: { profile: ProfileState; config: AppConfig }) {
  const [query, setQuery] = useState("");
  const [status, setStatus] = useState<"all" | "open" | "locked">("all");
  const [difficulty, setDifficulty] = useState("all");
  const [group, setGroup] = useState("all");
  const [onlyTitles, setOnlyTitles] = useState(false);
  const [onlyFragments, setOnlyFragments] = useState(false);
  const all = useMemo(() => allAchievementsWithProgress(profile, config), [profile, config]);
  const unlocked = new Set(profile.unlockedAchievementIds);
  const isUnlocked = (a: typeof all[number]) => unlocked.has(a.id) || a.currentValue >= a.threshold;
  const earned = all.filter(isUnlocked);
  const standard = all.filter((a) => a.rank >= 1 && a.rank <= 9);
  const titleAchievements = standard.filter((a) => Boolean(a.title));
  const completion = standard.length ? earned.filter((a) => a.rank >= 1 && a.rank <= 9).length / standard.length * 100 : 0;
  const fragmentOwned = Object.values(profile.fragments).reduce((sum, value) => sum + Math.max(0, Number(value) || 0), 0);
  const fragmentAssemblySize = 12;
  const assembledProducts = Math.floor(fragmentOwned / fragmentAssemblySize);
  const fragmentRemainder = fragmentOwned % fragmentAssemblySize;
  const titleWisdom = (rank: number) => rank >= 9 ? { quote: "Có công mài sắt, có ngày nên kim.", explanation: "Kiên trì với những bước nhỏ sẽ tạo nên thành quả lớn." } : rank >= 7 ? { quote: "Nước chảy đá mòn.", explanation: "Sự đều đặn có thể vượt qua những điều tưởng như rất khó." } : { quote: "Kiến tha lâu đầy tổ.", explanation: "Mỗi lần học là một phần đóng góp vào nền tảng hiểu biết." };
  const visible = all.filter((a) => {
    const open = isUnlocked(a);
    return (!query || [a.name, a.description, a.title ?? "", a.titleMeaning ?? ""].some((value) => value.toLowerCase().includes(query.toLowerCase()))) &&
      (status === "all" || (status === "open" ? open : !open)) &&
      (difficulty === "all" || a.difficulty === difficulty) &&
      (group === "all" || a.rankName === group) &&
      (!onlyTitles || Boolean(a.title)) && (!onlyFragments || a.rewardFragments > 0);
  });
  const prioritized = [...visible].sort((a, b) => Number(Boolean(b.title)) - Number(Boolean(a.title)) || a.rank - b.rank || a.id.localeCompare(b.id));
  return <>
    <Heading eyebrow="400 danh hiệu · 900 thành tích" title="Danh hiệu của Ong, rồi đến từng dấu mốc" text="Mọi mốc đều được công khai từ đầu. Ong không cần đạt 100%; mỗi dấu mốc đã mở khóa đều là một phần đáng ghi nhận của hành trình riêng." action={<span className="rounded-xl bg-green-50 px-4 py-2 text-sm font-bold text-green-700 dark:bg-green-500/10 dark:text-green-200">🌱 Đã mở {earned.length} dấu mốc</span>} />
    <section className="panel mb-5 p-5" aria-label="Tổng quan catalog thành tích">
      <div className="grid gap-4 md:grid-cols-4">
        <div><p className="text-xs font-bold uppercase tracking-[.16em] text-red-700 dark:text-red-300">Catalog công khai</p><p className="mt-1 text-2xl font-black">{standard.length}/900</p><p className="text-xs text-slate-500">thành tích đã công bố</p></div>
        <div><p className="text-xs font-bold uppercase tracking-[.16em] text-amber-700 dark:text-amber-300">Danh hiệu</p><p className="mt-1 text-2xl font-black">{titleAchievements.length}/400</p><p className="text-xs text-slate-500">mốc cuối khó nhất</p></div>
        <div><p className="text-xs font-bold uppercase tracking-[.16em] text-green-700 dark:text-green-300">Đã mở khóa</p><p className="mt-1 text-2xl font-black">{earned.filter((a) => a.rank <= 9).length}</p><p className="text-xs text-slate-500">dấu mốc của Ong</p></div>
        <div><p className="text-xs font-bold uppercase tracking-[.16em] text-amber-700 dark:text-amber-300">Mảnh ghép</p><p className="mt-1 text-2xl font-black">{fragmentOwned}</p><p className="text-xs text-slate-500">đã nhận · {Math.max(0, fragmentAssemblySize - fragmentRemainder)} nữa tới lần ghép kế</p></div>
      </div>
      <div className="mt-5 flex items-center justify-between gap-3 text-sm"><div><p className="font-bold">Ong đã mở khóa {earned.filter((a) => a.rank <= 9).length} dấu mốc trong hành trình của mình.</p><p className="mt-1 text-xs text-slate-500">Thanh này chỉ giúp nhìn lại tiến bộ; không phải bảng điểm bắt buộc.</p></div><strong className="text-green-700 dark:text-green-300">{Math.round(completion)}%</strong></div>
      <div className="mt-3 h-3 overflow-hidden rounded-full bg-slate-100 dark:bg-white/10" role="progressbar" aria-label="Tiến bộ trên 900 thành tích" aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(completion)}><div className="h-full rounded-full bg-gradient-to-r from-[#c62828] via-[#f4b942] to-[#2e7d32] transition-[width]" style={{ width: completion + "%" }} /></div>
    </section>
    <section className="panel mb-5 p-5" aria-label="Hệ thống mảnh ghép">
      <div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-amber-700 dark:text-amber-300">Hệ thống mảnh ghép</p><h2 className="mt-1 font-display text-xl font-bold">Nhận mảnh để mở khóa hồ sơ nhân vật lịch sử</h2><p className="mt-1 max-w-3xl text-sm leading-6 text-slate-500">Mỗi thành tích có ghi rõ số mảnh được nhận. Mảnh ghép dùng để sưu tầm, mở khóa và hoàn thiện hồ sơ nhân vật lịch sử; không dùng để ghép tranh.</p></div><span className="rounded-full bg-amber-100 px-3 py-1 text-xs font-bold text-amber-800">{fragmentOwned} mảnh đang sở hữu</span></div>
      <div className="mt-4 grid gap-3 sm:grid-cols-3"><div className="rounded-2xl border border-amber-100 bg-amber-50/60 p-3 dark:border-amber-400/15 dark:bg-amber-500/[.06]"><b className="text-sm">Đã nhận</b><p className="mt-1 text-2xl font-black text-amber-700">{fragmentOwned}</p><p className="text-xs text-slate-500">từ achievement, hoạt động học và phần thưởng được cấu hình</p></div><div className="rounded-2xl border border-green-100 bg-green-50/60 p-3 dark:border-green-400/15 dark:bg-green-500/[.06]"><b className="text-sm">Hồ sơ đã mở</b><p className="mt-1 text-2xl font-black text-green-700">{assembledProducts}</p><p className="text-xs text-slate-500">nhân vật/nội dung lịch sử đã hoàn thiện</p></div><div className="rounded-2xl border border-red-100 bg-red-50/60 p-3 dark:border-red-400/15 dark:bg-red-500/[.06]"><b className="text-sm">Giá trị quy đổi</b><p className="mt-1 text-2xl font-black text-red-700">{fragmentOwned}</p><p className="text-xs text-slate-500">dùng cho mở khóa hồ sơ, nâng cấp và đổi vé theo cấu hình</p></div></div>
    </section>
    <div className="panel mb-5 grid gap-3 p-4 sm:grid-cols-2 lg:grid-cols-6"><input value={query} onChange={(e) => setQuery(e.target.value)} className="input mt-0 lg:col-span-2" placeholder="Tìm thành tích, danh hiệu, ý nghĩa…" aria-label="Tìm thành tích hoặc danh hiệu" /><select value={group} onChange={(e) => setGroup(e.target.value)} className="input mt-0" aria-label="Lọc nhóm thành tích"><option value="all">Tất cả 9 nhóm</option>{Array.from(new Set(standard.map((a) => a.rankName))).map((x) => <option key={x}>{x}</option>)}</select><select value={status} onChange={(e) => setStatus(e.target.value as typeof status)} className="input mt-0" aria-label="Lọc trạng thái"><option value="all">Tất cả</option><option value="open">Đã mở khóa</option><option value="locked">🔒 Chưa đạt</option></select><select value={difficulty} onChange={(e) => setDifficulty(e.target.value)} className="input mt-0" aria-label="Lọc độ khó"><option value="all">Mọi độ khó</option>{["Dễ", "Bình thường", "Khó", "Rất khó", "Cực khó", "Huyền thoại"].map((x) => <option key={x}>{x}</option>)}</select><div className="flex flex-wrap items-center gap-3 text-xs font-bold"><label className="flex items-center gap-2"><input type="checkbox" checked={onlyTitles} onChange={(e) => setOnlyTitles(e.target.checked)} />Danh hiệu</label><label className="flex items-center gap-2"><input type="checkbox" checked={onlyFragments} onChange={(e) => setOnlyFragments(e.target.checked)} />Có mảnh</label></div></div>
    <p className="mb-3 text-sm font-bold text-slate-500">Đang hiển thị {prioritized.length}/{standard.length} mục công khai · {prioritized.filter((a) => a.title).length} danh hiệu được ưu tiên hiển thị trước</p>
    <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{prioritized.map((a) => { const open = isUnlocked(a); const wisdom = a.title ? titleWisdom(a.rank) : null; return <article key={a.id} className={cn("rounded-2xl border p-4", open ? "border-green-200 bg-green-50/50 dark:bg-green-400/10" : "border-slate-200 bg-white/60 dark:border-white/10 dark:bg-white/[.025]")}><div className="flex gap-3"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-white text-lg shadow-sm dark:bg-slate-800">{a.icon}</span><span className="min-w-0"><p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">#{standard.indexOf(a) + 1} · Nhóm {a.rank}: {a.rankName}</p><b className="block text-sm">{a.name}</b><p className="mt-1 text-xs leading-5 text-slate-500"><b>Điều kiện:</b> {a.description}</p></span></div><div className="mt-3 flex flex-wrap gap-2 text-[11px] font-bold"><span className="rounded-full bg-slate-100 px-2 py-1 text-slate-600 dark:bg-white/10 dark:text-amber-50/80">{a.difficulty}</span><span className={cn("rounded-full px-2 py-1", open ? "bg-green-100 text-green-700" : "bg-red-100 text-red-700")}>{open ? "Đã mở khóa" : "🔒 Chưa đạt"}</span><span className="rounded-full bg-amber-100 px-2 py-1 text-amber-800">+{a.rewardXp} XP</span>{a.rewardFragments > 0 && <span className="rounded-full bg-amber-100 px-2 py-1 text-amber-800">+{a.rewardFragments} mảnh</span>}</div><div className="mt-4"><div className="flex items-center justify-between gap-3 text-xs font-bold"><span>Tiến độ: {a.currentValue.toLocaleString("vi-VN")}/{a.threshold.toLocaleString("vi-VN")}</span><span className="text-green-700">{a.progress}%</span></div><div className="mt-2 h-2.5 overflow-hidden rounded-full bg-slate-100 dark:bg-white/10" role="progressbar" aria-label={"Tiến độ " + a.name} aria-valuemin={0} aria-valuemax={100} aria-valuenow={a.progress}><div className={cn("h-full rounded-full transition-[width]", open ? "bg-emerald-500" : "bg-amber-400")} style={{ width: a.progress + "%" }} /></div><p className="mt-2 text-xs leading-5 text-slate-500">{open ? "Ong đã đủ điều kiện cho mốc này." : <>Còn <b className="text-slate-700 dark:text-slate-200">{a.remaining.toLocaleString("vi-VN")}</b> {a.metric === "xp" ? "XP" : "đơn vị"} nữa.</>}</p></div>{a.title && <div className="mt-3 rounded-xl border border-amber-200 bg-gradient-to-r from-amber-100 to-yellow-50 p-3 dark:border-amber-400/30 dark:from-amber-400/15 dark:to-white/5"><p className="text-[10px] font-bold uppercase tracking-widest text-amber-700">Danh hiệu công khai · Nhóm {a.titleGroup ?? "—"}/8 · {a.titleGroupLabel ?? a.difficulty}</p><b className="mt-1 block text-sm text-amber-900 dark:text-amber-100">🔒 {a.title}</b><p className="mt-1 text-xs leading-5 text-amber-800/80 dark:text-amber-100/70"><b>Ý nghĩa:</b> {a.titleSignificance || a.titleMeaning || "Danh hiệu ghi nhận một chặng đường học tập bền bỉ."}</p><p className="mt-1 text-xs leading-5 text-amber-800/80 dark:text-amber-100/70"><b>Giải thích tên:</b> {a.titleMeaning || "Tên gọi ghi nhận tiến bộ của Ong."}</p>{a.titleInspiration && <p className="mt-2 text-xs font-bold text-amber-800 dark:text-amber-100">Nguồn/cảm hứng ({a.source_type === "verified" ? "đã xác minh" : "lấy cảm hứng từ"}): “{a.source_text || a.titleInspiration}”</p>}<p className="mt-1 text-xs leading-5 text-amber-800/80 dark:text-amber-100/70">{a.source_note || a.titleExplanation || wisdom?.explanation || "Nguồn văn hóa chưa được khẳng định; nội dung chỉ ghi là cảm hứng."}</p><p className="mt-2 text-xs font-bold text-amber-800 dark:text-amber-100">Phần thưởng danh hiệu: +{a.rewardXp} điểm · +{a.rewardFragments} mảnh lịch sử · +{a.exchangeTicketReward ?? 0} vé · {a.cosmeticReward || "vật phẩm trang trí theo cấu hình"}</p></div>}<p className="mt-3 text-xs text-slate-500">Phần thưởng: {a.rewardXp} XP{a.rewardFragments ? <> · {a.rewardFragments} mảnh dùng để mở khóa hồ sơ nhân vật lịch sử</> : ""}.</p></article>; })}</div>
  </>;
}

function Museum({ account, profile, config }: { account: StudyAccount; profile: ProfileState; config: AppConfig }) { if (!config.characters.length) return <><Heading eyebrow="Bảo tàng hành trình" title="Học để mở khóa những câu chuyện" text="Bảo tàng không có dữ liệu mặc định. Mọi nhân vật, nguồn và ảnh đều do Admin/Founder nhập vào." /><Empty icon={History} title="Chưa có dữ liệu nhân vật" text={isAdmin(account) ? "Mở Admin Panel để thêm nhân vật, tiểu sử, mốc lịch sử và nguồn tham khảo." : "Admin/Founder sẽ công bố dữ liệu lịch sử đã được xác minh khi sẵn sàng."} /></>; return <><Heading eyebrow="Bảo tàng hành trình" title="Học để mở khóa những câu chuyện" text="Thu thập mảnh ghép để khám phá các nhân vật lịch sử." /><div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-3">{config.characters.map((c) => { const owned = profile.fragments[c.id] ?? 0; const unlocked = owned >= c.fragmentTotal; return <article key={c.id} className="overflow-hidden rounded-3xl border border-slate-200 bg-white shadow-sm dark:border-white/10 dark:bg-slate-900"><div className="relative grid h-48 place-items-center bg-gradient-to-br from-[#8d5d15] to-amber-500">{c.imageUrl ? <img src={c.imageUrl} alt={unlocked ? c.name : "Nhân vật đang khóa"} className={cn("h-full w-full object-cover", !unlocked && "blur-md brightness-50")} /> : <History className="h-12 w-12 text-white/30" />}{!unlocked && <LockKeyhole className="absolute h-7 w-7 text-white" />}</div><div className="p-5"><p className="text-xs font-bold uppercase tracking-widest text-amber-700">{c.role || "Nhân vật lịch sử"}</p><h2 className="mt-1 font-display text-xl font-bold">{unlocked ? c.name : "Nhân vật chưa mở khóa"}</h2><p className="mt-2 text-sm leading-6 text-slate-500">{unlocked ? c.summary || "Chưa có mô tả." : "Thu thập mảnh ghép để khám phá câu chuyện."}</p><Progress value={owned / c.fragmentTotal * 100} className="mt-4" /><p className="mt-2 text-xs font-bold text-slate-500">{owned}/{c.fragmentTotal} mảnh ghép</p></div></article>; })}</div></>; }
function Wheel({ profile, config, onProfile }: { profile: ProfileState; config: AppConfig; onProfile: (p: ProfileState, m?: string) => void }) { const [spinning, setSpinning] = useState(false); const [result, setResult] = useState(""); const spin = () => { if (!profile.wheelTickets) return toast.error("Bạn chưa có vé quay."); if (!config.wheelRewards.length) return toast.error("Vòng quay chưa được cấu hình."); setSpinning(true); const availableRewards = config.wheelRewards.filter((item) => item.enabled !== false); if (!availableRewards.length) return toast.error("Vòng quay hiện không có phần thưởng đang bật."); const reward = availableRewards[Math.floor(Math.random() * availableRewards.length)]; setTimeout(() => { const next = { ...profile, wheelTickets: profile.wheelTickets - 1, xp: profile.xp + (reward.kind === "xp" ? reward.value : 0) }; next.level = levelForXp(next.xp); onProfile(next, `Nhận được ${reward.label}.`); setResult(reward.label); setSpinning(false); }, 1000); }; return <><Heading eyebrow="Vòng quay tri thức" title="Một phần thưởng cho nỗ lực học tập" text="Admin/Founder cấu hình phần thưởng, màu sắc và tỷ lệ quay." action={<span className="rounded-xl bg-amber-50 px-4 py-2 text-sm font-bold text-amber-800">{profile.wheelTickets} vé</span>} /><div className="grid gap-5 lg:grid-cols-2"><section className="grid min-h-96 place-items-center rounded-[2rem] bg-gradient-to-br from-[#4b2e1f] via-[#805b32] to-[#b67b2d] p-8 text-center text-white"><div className={cn("grid h-64 w-64 place-items-center rounded-full border-[14px] border-white/80 bg-[conic-gradient(#f4c95d_0deg_70deg,#b67b2d_70deg_150deg,#ead7a1_150deg_220deg,#8f6b3d_220deg_300deg,#d8923d_300deg_360deg)]", spinning && "animate-spin")}><span className="grid h-32 w-32 place-items-center rounded-full bg-[#2d211a] font-display font-bold">TRI THỨC</span></div><button onClick={spin} disabled={spinning} className="mt-8 rounded-xl bg-amber-300 px-6 py-3 text-sm font-bold text-[#2d211a] disabled:opacity-50">{spinning ? "Đang quay…" : "Quay ngay"}</button>{result && <p className="mt-4 text-sm font-bold text-amber-200">Phần thưởng: {result}</p>}</section><section className="panel p-6"><p className="text-xs font-bold uppercase tracking-widest text-slate-400">Bảng phần thưởng</p>{config.wheelRewards.length ? <div className="mt-4 grid gap-3 sm:grid-cols-2">{config.wheelRewards.map((r) => <div className="rounded-2xl border border-slate-100 p-4 dark:border-white/10" key={r.id}><span className="block h-2 w-10 rounded-full" style={{ background: r.color }} /><b className="mt-3 block text-sm">{r.label}</b><small className="text-slate-500">Tỷ lệ {r.probability}% · Giá trị {r.value}</small></div>)}</div> : <Empty icon={Dices} title="Chưa có phần thưởng" text="Admin/Founder cần cấu hình ít nhất một ô quay." />}</section></div></>; }
function Account({ account, profile, config, onProfile, onLogout }: { account: StudyAccount; profile: ProfileState; config: AppConfig; onProfile: (p: ProfileState, m?: string) => void; onLogout: () => void }) { const exportData = () => { const blob = new Blob([JSON.stringify({ profile }, null, 2)], { type: "application/json" }); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = "study-historia-backup.json"; a.click(); URL.revokeObjectURL(url); }; const importData = (e: ChangeEvent<HTMLInputElement>) => { const file = e.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { try { onProfile(normalizeProfile(JSON.parse(String(reader.result)).profile ?? JSON.parse(String(reader.result))), "Đã nhập dữ liệu cá nhân."); } catch { toast.error("Tệp JSON không hợp lệ."); } }; reader.readAsText(file); }; return <><Heading eyebrow="Tài khoản cá nhân" title="Dữ liệu của bạn, hành trình của bạn" text="Hồ sơ học tập được cô lập theo mã tài khoản, có thể sao lưu và khôi phục bằng JSON." /><div className="grid gap-5 lg:grid-cols-2"><section className="rounded-3xl bg-gradient-to-br from-[#8d5d15] to-amber-500 p-6 text-white"><p className="text-xs font-bold uppercase tracking-widest text-amber-100">Hồ sơ thành viên</p><h2 className="mt-3 font-display text-3xl font-bold">{account.name}</h2><p className="mt-1 text-amber-100">{account.role} · Mã {account.code}</p><p className="mt-8 text-xl font-bold">Cấp {profile.level} · {profile.xp} XP</p></section><section className="panel p-6"><h2 className="font-display text-2xl font-bold">Sao lưu và riêng tư</h2><p className="mt-3 text-sm leading-6 text-slate-500">Bản sao lưu chỉ gồm dữ liệu học tập của tài khoản hiện tại, không chứa mật khẩu hay dữ liệu thành viên khác.</p><div className="mt-6 flex flex-wrap gap-3"><button onClick={exportData} className="primary-button"><Download className="h-4 w-4" />Xuất JSON</button><label className="secondary-button cursor-pointer"><FileUp className="h-4 w-4" />Nhập JSON<input type="file" className="hidden" accept="application/json" onChange={importData} /></label><button onClick={onLogout} className="secondary-button text-rose-600">Đăng xuất</button></div></section></div><ProfileTitleSelector profile={profile} config={config} onProfile={onProfile} /></>; }
export function Admin({ account, config, onConfig }: { account: StudyAccount; config: AppConfig; onConfig: (c: AppConfig, m?: string) => void }) { const [tab, setTab] = useState<"characters" | "wheel" | "achievements">("characters"); const [name, setName] = useState(""); const [reward, setReward] = useState(""); const [achievementName, setAchievementName] = useState(""); const [achievementDescription, setAchievementDescription] = useState(""); const [achievementMetric, setAchievementMetric] = useState<AppConfig["customAchievements"][number]["metric"]>("learnedCards"); const [achievementThreshold, setAchievementThreshold] = useState("10"); const [achievementXp, setAchievementXp] = useState("50"); const [achievementFragments, setAchievementFragments] = useState("0"); const [achievementTitle, setAchievementTitle] = useState(""); const [editingAchievement, setEditingAchievement] = useState<string | null>(null); const metricLabels: Record<AppConfig["customAchievements"][number]["metric"], string> = { xp: "XP", learnedCards: "Flashcard đã học thuộc", completedQuizzes: "Bài kiểm tra hoàn thành", completedSets: "Bộ Flashcard hoàn thành", pomodoroSessions: "Phiên Pomodoro hoàn thành" }; if (!isAdmin(account)) return <Empty icon={ShieldCheck} title="Khu vực giới hạn" text="Chỉ Admin và Founder có quyền truy cập." />; const addCharacter = () => { if (!name.trim()) return toast.error("Nhập tên nhân vật trước khi thêm."); onConfig({ ...config, characters: [{ id: uid(), name, aliases: "", birthYear: "", deathYear: "", hometown: "", role: "", categories: [], summary: "", biography: "", sourceName: "", sourceUrl: "", imageUrl: "", imageSource: "", fragmentTotal: 12, timeline: [], updatedAt: new Date().toISOString() }] }, "Đã thêm khung nhân vật. Hãy bổ sung nguồn và tiểu sử đã kiểm chứng."); setName(""); }; const addReward = () => { if (!reward.trim()) return toast.error("Nhập tên phần thưởng."); onConfig(addWheelReward(config, { label: reward.trim(), kind: "xp", value: 20, probability: 20, color: "#22d3ee", enabled: true }, uid()), "Đã thêm phần thưởng mẫu."); setReward(""); }; const addAchievement = () => { const threshold = Math.max(1, Number(achievementThreshold) || 0); const rewardXp = Math.max(0, Number(achievementXp) || 0); const rewardFragments = Math.max(0, Number(achievementFragments) || 0); if (!achievementName.trim() || !achievementDescription.trim()) return toast.error("Nhập tên và điều kiện thành tích."); const item = { id: uid(), name: achievementName.trim(), description: achievementDescription.trim(), metric: achievementMetric, threshold, rewardXp, rewardFragments, title: achievementTitle.trim() || undefined, enabled: true }; onConfig(addCustomAchievement(config, item, item.id), "Đã tạo mốc thành tích. Mốc này chưa được trao cho ai; thành viên phải tự đạt điều kiện."); setAchievementName(""); setAchievementDescription(""); setAchievementTitle(""); }; const removeAchievement = (id: string) => onConfig(deleteCustomAchievement(config, id), "Đã xóa mốc thành tích."); const toggleAchievement = (id: string) => onConfig(toggleCustomAchievement(config, id), "Đã cập nhật trạng thái mốc."); const editAchievement = (item: AppConfig["customAchievements"][number]) => { setEditingAchievement(item.id); setAchievementName(item.name); setAchievementDescription(item.description); setAchievementMetric(item.metric); setAchievementThreshold(String(item.threshold)); setAchievementXp(String(item.rewardXp)); setAchievementFragments(String(item.rewardFragments)); setAchievementTitle(item.title ?? ""); }; const cancelEditAchievement = () => { setEditingAchievement(null); setAchievementName(""); setAchievementDescription(""); setAchievementThreshold("10"); setAchievementXp("50"); setAchievementFragments("0"); setAchievementTitle(""); }; const saveEditAchievement = () => { if (!editingAchievement || !achievementName.trim() || !achievementDescription.trim()) return toast.error("Nhập tên và điều kiện thành tích."); const threshold = Number(achievementThreshold); const rewardXp = Number(achievementXp); const rewardFragments = Number(achievementFragments); if (!Number.isFinite(threshold) || threshold < 1 || !Number.isFinite(rewardXp) || rewardXp < 0 || !Number.isFinite(rewardFragments) || rewardFragments < 0) return toast.error("Mục tiêu hoặc phần thưởng không hợp lệ."); onConfig({ ...config, customAchievements: config.customAchievements.map((entry) => entry.id === editingAchievement ? { ...entry, name: achievementName.trim(), description: achievementDescription.trim(), metric: achievementMetric, threshold, rewardXp, rewardFragments, title: achievementTitle.trim() || undefined } : entry) }, "Đã cập nhật mốc thành tích."); cancelEditAchievement(); }; const editReward = (item: AppConfig["wheelRewards"][number]) => { const label = window.prompt("Tên phần thưởng", item.label); if (label === null) return; const value = Number(window.prompt("Giá trị phần thưởng", String(item.value))); if (!Number.isFinite(value) || value < 0) return toast.error("Giá trị không hợp lệ."); const probability = Number(window.prompt("Tỷ lệ phần trăm", String(item.probability))); if (!Number.isFinite(probability) || probability < 0 || probability > 100) return toast.error("Tỷ lệ phải từ 0 đến 100."); onConfig({ ...config, wheelRewards: config.wheelRewards.map((entry) => entry.id === item.id ? { ...entry, label: label.trim() || entry.label, value, probability } : entry) }, "Đã cập nhật phần thưởng."); }; const toggleReward = (id: string) => onConfig({ ...config, wheelRewards: config.wheelRewards.map((item) => item.id === id ? { ...item, enabled: item.enabled === false } : item) }, "Đã cập nhật trạng thái phần thưởng."); return <><Heading eyebrow="Khu vực quản trị" title="Cấu hình hệ sinh thái học tập" text="Admin/Founder có thể tự tạo mốc và phần thưởng. Cấu hình mẫu được đánh dấu Mẫu khởi đầu; không làm phát sinh thành tích đã đạt cho thành viên." /><div className="flex flex-wrap gap-2"><button onClick={() => setTab("characters")} className={cn("filter-pill", tab === "characters" && "active")}>Nhân vật</button><button onClick={() => setTab("wheel")} className={cn("filter-pill", tab === "wheel" && "active")}>Vòng quay</button><button onClick={() => setTab("achievements")} className={cn("filter-pill", tab === "achievements" && "active")}>Mốc thành tích</button></div>{tab === "characters" ? <section className="panel mt-5 p-5"><h2 className="font-display text-xl font-bold">Thêm nhân vật lịch sử</h2><p className="mt-2 text-sm text-slate-500">Không có dữ liệu mẫu. Chỉ nhập nội dung đã xác minh, kèm nguồn và ảnh trong quy trình biên tập tiếp theo.</p><div className="mt-5 flex flex-col gap-3 sm:flex-row"><input value={name} onChange={(e) => setName(e.target.value)} className="input mt-0 flex-1" placeholder="Tên nhân vật" /><button onClick={addCharacter} className="primary-button"><Plus className="h-4 w-4" />Thêm khung</button></div><div className="mt-6 space-y-2">{config.characters.length ? config.characters.map((x) => <div key={x.id} className="flex justify-between rounded-xl border border-slate-100 p-3 dark:border-white/10"><b>{x.name}</b><button onClick={() => onConfig({ ...config, characters: config.characters.filter((c) => c.id !== x.id) }, "Đã xóa nhân vật.")} className="text-rose-600"><X className="h-4 w-4" /></button></div>) : <Empty icon={History} title="Danh sách trống" text="Thêm nhân vật khi đã có nội dung và nguồn hợp lệ." />}</div></section> : tab === "wheel" ? <section className="panel mt-5 p-5"><h2 className="font-display text-xl font-bold">Cấu hình Vòng quay</h2><p className="mt-2 text-sm text-slate-500">Các phần thưởng mẫu chỉ là cấu hình khởi đầu. Admin có thể xóa hoặc thêm phần thưởng thật của hệ thống.</p><div className="mt-5 flex flex-col gap-3 sm:flex-row"><input value={reward} onChange={(e) => setReward(e.target.value)} className="input mt-0 flex-1" placeholder="Ví dụ: +20 XP" /><button onClick={addReward} className="primary-button"><Plus className="h-4 w-4" />Thêm phần thưởng</button></div><div className="mt-6 grid gap-2">{config.wheelRewards.map((x) => <div key={x.id} className="flex items-center justify-between gap-3 rounded-xl border border-slate-100 p-3 dark:border-white/10"><span><b>{x.label}</b><small className="ml-2 text-slate-500">{x.probability}% · {x.value} {x.kind}</small></span><div className="flex flex-wrap gap-2"><button onClick={() => editReward(x)} className="secondary-button text-xs">Sửa</button><button onClick={() => toggleReward(x.id)} className="secondary-button text-xs">{x.enabled === false ? "Bật lại" : "Tạm tắt"}</button><button onClick={() => onConfig({ ...config, wheelRewards: config.wheelRewards.filter((r) => r.id !== x.id) }, "Đã xóa phần thưởng.")} className="secondary-button text-xs text-rose-600"><X className="h-4 w-4" />Xóa</button></div></div>)}</div></section> : <section className="mt-5 grid gap-5 lg:grid-cols-[.9fr_1.1fr]"><div className="panel p-5">{editingAchievement ? <div className="mb-6 rounded-2xl border-2 border-amber-200 bg-amber-50/60 p-4 dark:border-amber-400/30 dark:bg-amber-400/10"><div className="flex items-center justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-widest text-amber-700">Đang chỉnh sửa</p><h2 className="mt-1 font-display text-xl font-bold">Cập nhật mốc thành tích</h2></div><button type="button" onClick={cancelEditAchievement} className="secondary-button text-xs">Hủy</button></div><div className="mt-4 grid gap-3"><input value={achievementName} onChange={(e) => setAchievementName(e.target.value)} className="input mt-0" placeholder="Tên mốc" aria-label="Tên mốc đang chỉnh sửa" /><textarea value={achievementDescription} onChange={(e) => setAchievementDescription(e.target.value)} className="input mt-0 min-h-20" placeholder="Điều kiện mở khóa" aria-label="Điều kiện mốc đang chỉnh sửa" /><select value={achievementMetric} onChange={(e) => setAchievementMetric(e.target.value as typeof achievementMetric)} className="input mt-0" aria-label="Chỉ số mốc đang chỉnh sửa">{Object.entries(metricLabels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select><div className="grid gap-3 sm:grid-cols-3"><input value={achievementThreshold} onChange={(e) => setAchievementThreshold(e.target.value)} type="number" min="1" className="input mt-0" placeholder="Mục tiêu" aria-label="Mục tiêu đang chỉnh sửa" /><input value={achievementXp} onChange={(e) => setAchievementXp(e.target.value)} type="number" min="0" className="input mt-0" placeholder="XP thưởng" aria-label="XP thưởng đang chỉnh sửa" /><input value={achievementFragments} onChange={(e) => setAchievementFragments(e.target.value)} type="number" min="0" className="input mt-0" placeholder="Mảnh ghép" aria-label="Mảnh ghép đang chỉnh sửa" /></div><input value={achievementTitle} onChange={(e) => setAchievementTitle(e.target.value)} className="input mt-0" placeholder="Danh hiệu tùy chọn" aria-label="Danh hiệu đang chỉnh sửa" /><div className="flex flex-wrap gap-3"><button type="button" onClick={saveEditAchievement} className="primary-button">Lưu thay đổi</button><button type="button" onClick={cancelEditAchievement} className="secondary-button">Hủy chỉnh sửa</button></div></div></div> : null}<h2 className="font-display text-xl font-bold">{editingAchievement ? "Tạo mốc thành tích mới" : "Tạo mốc thành tích"}</h2><p className="mt-2 text-sm leading-6 text-slate-500">Nhập điều kiện đo được. Thành tích chỉ mở khi tiến độ thành viên đạt đúng mốc; thao tác này không cấp thưởng ngay.</p><div className="mt-4 grid gap-3"><input value={achievementName} onChange={(e) => setAchievementName(e.target.value)} className="input mt-0" placeholder="Tên mốc, ví dụ: 10 phút tập trung" /><textarea value={achievementDescription} onChange={(e) => setAchievementDescription(e.target.value)} className="input mt-0 min-h-20" placeholder="Điều kiện hiển thị cho thành viên" /><select value={achievementMetric} onChange={(e) => setAchievementMetric(e.target.value as typeof achievementMetric)} className="input mt-0">{Object.entries(metricLabels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select><div className="grid gap-3 sm:grid-cols-3"><input value={achievementThreshold} onChange={(e) => setAchievementThreshold(e.target.value)} type="number" min="1" className="input mt-0" placeholder="Mục tiêu" /><input value={achievementXp} onChange={(e) => setAchievementXp(e.target.value)} type="number" min="0" className="input mt-0" placeholder="XP thưởng" /><input value={achievementFragments} onChange={(e) => setAchievementFragments(e.target.value)} type="number" min="0" className="input mt-0" placeholder="Mảnh ghép" /></div><input value={achievementTitle} onChange={(e) => setAchievementTitle(e.target.value)} className="input mt-0" placeholder="Danh hiệu tùy chọn" /><button onClick={addAchievement} className="primary-button"><Plus className="h-4 w-4" />Tạo mốc</button></div></div><div className="panel p-5"><div className="flex items-center justify-between gap-3"><div><h2 className="font-display text-xl font-bold">Mốc đang cấu hình</h2><p className="mt-1 text-sm text-slate-500">{config.customAchievements.length} mốc · {config.customAchievements.filter((item) => item.enabled).length} đang áp dụng</p></div><span className="rounded-full bg-amber-100 px-3 py-1 text-xs font-bold text-amber-800">Không giả lập tiến độ</span></div><div className="mt-5 space-y-3">{config.customAchievements.map((item) => <div key={item.id} className="rounded-2xl border border-slate-100 p-4 dark:border-white/10"><div className="flex items-start justify-between gap-3"><div><b>{item.name}</b><p className="mt-1 text-xs leading-5 text-slate-500">{item.description}</p><p className="mt-2 text-xs font-bold text-amber-700">Mục tiêu: {item.threshold} · {metricLabels[item.metric]} · +{item.rewardXp} XP{item.rewardFragments ? <> · {item.rewardFragments} mảnh</> : null}</p></div><span className="rounded-full bg-slate-100 px-2 py-1 text-[10px] font-bold dark:bg-white/10">{item.enabled ? "Đang áp dụng" : "Tạm tắt"}</span></div><div className="mt-3 flex flex-wrap gap-2"><button onClick={() => editAchievement(item)} className="secondary-button text-xs">Sửa</button><button onClick={() => toggleAchievement(item.id)} className="secondary-button text-xs">{item.enabled ? "Tạm tắt" : "Bật lại"}</button><button onClick={() => removeAchievement(item.id)} className="secondary-button text-xs text-rose-600">Xóa mốc</button></div></div>)}</div></div></section>}</>; }
